counters.vanilla:
// Independent counters, plain DOM (hand-optimized): the spans are cloned from one prototype, each counter's text node
// and value are kept in arrays, and a fired timer writes only that counter's text.
import type { Counter, Fired } from "./def.ts"
import type { ScenarioApp } from "../core.ts"

export function mount(host: HTMLElement, data: Counter[]): ScenarioApp {
  const doc = host.ownerDocument
  const grid = doc.createElement("div"), proto = doc.createElement("span")
  grid.className = "cg"; proto.className = "ct"; proto.append("0")
  const texts: Text[] = [], n = data.map(() => 0)
  for (let i = 0; i < data.length; i++) {
    const s = proto.cloneNode(true) as HTMLElement
    texts.push(s.firstChild as Text)
    grid.append(s)
  }
  host.append(grid)
  return {
    step: (p) => { for (const i of p as Fired) texts[i]!.data = String(++n[i]!) },
    destroy: () => grid.remove(),
  }
}

counters.march:
// Independent counters, March: each Counter component owns its value (`let $n = 0` in the body is a signal) and
// registers its increment; a step calls the fired counters' increments inside batch(), and only their text updates.
import { render, batch } from "march"
import type { Counter as Model, Fired } from "./def.ts"
import type { ScenarioApp } from "../core.ts"

export function mount(host: HTMLElement, data: Model[]): ScenarioApp {
  const inc: (() => void)[] = []
  function Counter(p: { i: number }) {
    let $n = 0
    inc[p.i] = () => { $n++ }
    return <span class="ct">{$n}</span>
  }
  const dispose = render(() => <div class="cg">{data.map((_, i) => <Counter i={i} />)}</div>, host)
  return {
    step: (p) => batch(() => { for (const i of p as Fired) inc[i]!() }),
    destroy: dispose,
  }
}

counters.react:
// Independent counters, React 19: each Counter is a memo component with its own useReducer state and registers its
// dispatch; a step dispatches to the fired counters only (the grid does not render again), inside flushSync.
import { createElement as h, memo, useReducer, useLayoutEffect } from "react"
import { flushSync } from "react-dom"
import { createRoot } from "react-dom/client"
import type { Counter as Model, Fired } from "./def.ts"
import type { ScenarioApp } from "../core.ts"

const add1 = (n: number) => n + 1
export function mount(host: HTMLElement, data: Model[]): ScenarioApp {
  const inc: ((() => void) | null)[] = data.map(() => null)
  const Counter = memo(function Counter({ i }: { i: number }) {
    const [n, bump] = useReducer(add1, 0)
    useLayoutEffect(() => { inc[i] = bump as () => void; return () => { inc[i] = null } }, [i])
    return h("span", { className: "ct" }, n)
  })
  const App = () => h("div", { className: "cg" }, data.map((c, i) => h(Counter, { key: c.id, i })))
  const root = createRoot(host)
  flushSync(() => root.render(h(App)))
  return {
    step: (p) => flushSync(() => { for (const i of p as Fired) inc[i]!() }),
    destroy: () => root.unmount(),
  }
}

counters.preact:
// Independent counters, Preact 10: each Counter is a function component with its own useReducer state and registers
// its dispatch; a step dispatches to the fired counters only (the grid does not render again). Preact renders in a
// microtask, before the paint.
import { h, render } from "preact"
import { useReducer, useLayoutEffect } from "preact/hooks"
import type { Counter as Model, Fired } from "./def.ts"
import type { ScenarioApp } from "../core.ts"

const add1 = (n: number) => n + 1
export function mount(host: HTMLElement, data: Model[]): ScenarioApp {
  const inc: ((() => void) | null)[] = data.map(() => null)
  function Counter({ i }: { i: number }) {
    const [n, bump] = useReducer(add1, 0)
    useLayoutEffect(() => { inc[i] = bump as () => void; return () => { inc[i] = null } }, [i])
    return h("span", { class: "ct" }, n)
  }
  render(h("div", { class: "cg" }, data.map((c, i) => h(Counter, { key: c.id, i }))), host)
  return {
    step: (p) => { for (const i of p as Fired) inc[i]!() },
    destroy: () => render(null, host),
  }
}

counters.vue:
// ── vue-counter.template.html
<span class="ct">{{ n }}</span>

// ── vue.template.html
<div class="cg"><CounterView v-for="c of counters" :key="c.id" :i="c.i" /></div>

// ── vue.ts
// Independent counters, Vue 3: each Counter component owns a ref and registers its increment; a step increments the
// fired counters and Vue re-renders only those components (templates compiled ahead of time: vue.template.html,
// vue-counter.template.html → *.render.gen.js). Vue renders in a microtask, before the paint.
import { createApp, defineComponent, ref, markRaw } from "vue"
import { render as gridRender } from "./vue.render.gen.js"
import { render as counterRender } from "./vue-counter.render.gen.js"
import type { Counter as Model, Fired } from "./def.ts"
import type { ScenarioApp } from "../core.ts"

export function mount(host: HTMLElement, data: Model[]): ScenarioApp {
  const inc: (() => void)[] = []
  const counters = markRaw(data.map((c, i) => ({ id: c.id, i })))
  const CounterView = defineComponent({
    props: { i: { type: Number, required: true } },
    setup(props) { const n = ref(0); inc[props.i] = () => { n.value++ }; return { n } },
    render: counterRender,
  })
  const App = defineComponent({ components: { CounterView }, setup: () => ({ counters }), render: gridRender })
  const app = createApp(App)
  app.mount(host)
  return {
    step: (p) => { for (const i of p as Fired) inc[i]!() },
    destroy: () => app.unmount(),
  }
}

counters.solid:
// Independent counters, SolidJS: each Counter component owns a signal and registers its increment; a step calls the
// fired counters' increments inside batch() and Solid updates only their text. Compiled with babel-preset-solid
// (tools/gen-bench.mjs → solid.gen.js).
import { createSignal, batch } from "solid-js"
import { render } from "solid-js/web"

export function mount(host, data) {
  const inc = []
  function Counter(props) {
    const [n, setN] = createSignal(0)
    inc[props.i] = () => setN((v) => v + 1)
    return <span class="ct">{n()}</span>
  }
  const dispose = render(() => <div class="cg">{data.map((_, i) => <Counter i={i} />)}</div>, host)
  return {
    step: (fired) => batch(() => { for (const i of fired) inc[i]() }),
    destroy: dispose,
  }
}

counters.lit:
// Independent counters, Lit 3: the usual Lit pattern, each counter's value kept in its own slot and a render() of the
// whole grid per step; lit-html walks every counter's value and touches the DOM only where it changed. Counter
// template in compiled form (../lit-tpl.ts), as the CSP refuses HTML strings.
import { render } from "lit/html.js"
import { template, el, child } from "../lit-tpl.ts"
import type { Counter as Model, Fired } from "./def.ts"
import type { ScenarioApp } from "../core.ts"

export function mount(host: HTMLElement, data: Model[]): ScenarioApp {
  const counter = template(el("span", { class: "ct" }, child()))
  const n = data.map(() => 0)
  const grid = document.createElement("div")
  grid.className = "cg"; host.append(grid)
  const draw = () => render(n.map((v) => counter(v)), grid)
  draw()
  return {
    step: (p) => { for (const i of p as Fired) n[i]!++; draw() },
    destroy: () => { render(null, grid); grid.remove() },
  }
}

counters.inferno:
// Independent counters, Inferno: each Counter is a class component holding its own count and registering its
// increment; a step increments the fired counters, each calling its own forceUpdate() (synchronous in Inferno), so
// the grid itself does not render again. Compiled with babel-plugin-inferno (tools/gen-bench.mjs → inferno.gen.js).
import { render, Component } from "inferno"

export function mount(host, data) {
  const inc = []
  class Counter extends Component {
    constructor(props) { super(props); this.n = 0; inc[props.i] = () => { this.n++; this.forceUpdate() } }
    render() { return <span className="ct">{this.n}</span> }
  }
  render(<div className="cg" $HasKeyedChildren>{data.map((c, i) => <Counter key={c.id} i={i} />)}</div>, host)
  return {
    step: (fired) => { for (const i of fired) inc[i]() },
    destroy: () => render(null, host),
  }
}

counters.ivi:
// Independent counters, ivi: each Counter is a stateful component with its own count (useState) and registers its
// increment; a step increments the fired counters, which invalidates only them (ivi updates them in a microtask,
// before the paint). Templates compiled with ivi's template compiler (tools/gen-bench.mjs → ivi.gen.js).
import { createRoot, update, component, useState, html } from "ivi"
import type { Counter as Model, Fired } from "./def.ts"
import type { ScenarioApp } from "../core.ts"

export function mount(host: HTMLElement, data: Model[]): ScenarioApp {
  const inc: (() => void)[] = []
  const Counter = component<number>((c) => {
    const [n, setN] = useState(c, 0)
    return (i) => { inc[i] ??= () => setN(n() + 1); return html`<span class="ct">${n()}</span>` }
  }, () => true)
  const root = createRoot(host)
  update(root, html`<div class="cg">${data.map((_, i) => Counter(i))}</div>`)
  return {
    step: (p) => { for (const i of p as Fired) inc[i]!() },
    destroy: () => update(root, null),
  }
}

counters.mithril:
// Independent counters, Mithril: the counts are app state (Mithril components keep no state that redraws on its own);
// a step increments the fired counts and redraws once (m.redraw.sync), and each counter component skips its diff
// unless its count changed (onbeforeupdate).
import m from "mithril"
import type { Counter as Model, Fired } from "./def.ts"
import type { ScenarioApp } from "../core.ts"

const Counter: m.Component<{ n: number }> = {
  onbeforeupdate: (v, old) => v.attrs.n !== old.attrs.n,
  view: ({ attrs }) => m("span.ct", attrs.n),
}
export function mount(host: HTMLElement, data: Model[]): ScenarioApp {
  const n = data.map(() => 0)
  m.mount(host, { view: () => m("div.cg", data.map((c, i) => m(Counter, { key: c.id, n: n[i]! }))) })
  return {
    step: (p) => { for (const i of p as Fired) n[i]!++; m.redraw.sync() },
    destroy: () => m.mount(host, null),
  }
}

counters.alpine:
// Independent counters, Alpine.js (CSP build): each counter is its own reactive object and its x-text reads only its
// count, so a step re-runs just the fired counters' bindings, in Alpine's microtask (before the paint).
import Alpine from "@alpinejs/csp"
import { el, start } from "../../apps/alpine-dom.ts"
import type { Counter as Model, Fired } from "./def.ts"
import type { ScenarioApp } from "../core.ts"

export function mount(host: HTMLElement, data: Model[]): ScenarioApp {
  // <div class="cg"><template x-for="c in counters" :key="c.id"><span class="ct" x-text="c.n"></span></template></div>
  const root = el("div", { class: "cg" }, el("template", { "x-for": "c in counters", "x-bind:key": "c.id" }, el("span", { class: "ct", "x-text": "c.n" })))
  const s = start(host, root, { counters: data.map((c) => ({ id: c.id, n: 0 })) })
  return {
    step: (p) => { for (const i of p as Fired) s.counters[i]!.n++ },
    destroy: () => { Alpine.destroyTree(root); root.remove() },
  }
}

counters.angular:
// Independent counters, Angular: each counter is an OnPush component with its own count signal and registers its
// increment; a step increments the fired counters, so only their views refresh. Compiled ahead of time with the
// benchmark app (tools/gen-bench.mjs → ../../apps/angular.gen.js).
import { ChangeDetectionStrategy, Component, Input, signal, type OnInit } from "@angular/core"
import { mountRoot } from "../angular-host.ts"
import type { Counter as Model, Fired } from "./def.ts"
import type { ScenarioApp } from "../core.ts"

@Component({ selector: "span[ctr]", host: { class: "ct" }, changeDetection: ChangeDetectionStrategy.OnPush, template: `{{ n() }}` })
class CounterView implements OnInit {
  @Input({ required: true }) i!: number
  @Input({ required: true }) inc!: (() => void)[]
  readonly n = signal(0)
  ngOnInit(): void { this.inc[this.i] = () => this.n.update((v) => v + 1) }
}

@Component({
  selector: "bench-counters", changeDetection: ChangeDetectionStrategy.OnPush, imports: [CounterView],
  template: `<div class="cg">@for (c of counters; track c.id; let i = $index) {<span ctr [i]="i" [inc]="inc"></span>}</div>`,
})
class Counters { @Input({ required: true }) counters!: Model[]; @Input({ required: true }) inc!: (() => void)[] }

export async function mount(host: HTMLElement, data: Model[]): Promise<ScenarioApp> {
  const inc: (() => void)[] = []
  const app = await mountRoot(Counters, host, "bench-counters", { counters: data, inc })
  return { step: (p) => app.now(() => { for (const i of p as Fired) inc[i]!() }), destroy: app.destroy }
}

deep.vanilla:
// State at the top, plain DOM (hand-optimized): the hierarchy is built once from cloned prototypes, and the page keeps
// references to what depends on the state: each item's element and the measured items' value text nodes. A focus
// step changes the class of the old and the new item; a unit step rewrites the measured values.
import { FIRST_UNIT, NO_FOCUS, fmt, itemText, itemClass, type Deep, type Step } from "./def.ts"
import type { ScenarioApp } from "../core.ts"

export function mount(host: HTMLElement, data: Deep): ScenarioApp {
  const doc = host.ownerDocument
  const mk = (tag: string, cls: string, ...kids: Node[]) => { const e = doc.createElement(tag); if (cls) e.className = cls; e.append(...kids); return e }
  const pProto = mk("section", "pnl", mk("h3", "", doc.createTextNode("")), mk("p", "note", doc.createTextNode("")), mk("div", "grps"))
  const gProto = mk("div", "grp", mk("h4", "", doc.createTextNode("")))
  const iProto = mk("div", itemClass(false), mk("span", "k", doc.createTextNode("")), mk("b", "v", doc.createTextNode("")))
  const root = mk("div", "deep")
  const els: HTMLElement[] = [], vals: Text[] = [], metres: number[] = []
  for (const p of data.panels) {
    const pe = pProto.cloneNode(true) as HTMLElement
    ;(pe.firstChild!.firstChild as Text).data = p.title
    ;(pe.childNodes[1]!.firstChild as Text).data = p.note
    const grps = pe.lastChild!
    for (const g of p.groups) {
      const ge = gProto.cloneNode(true) as HTMLElement
      ;(ge.firstChild!.firstChild as Text).data = g.title
      for (const it of g.items) {
        const ie = iProto.cloneNode(true) as HTMLElement
        ;(ie.firstChild!.firstChild as Text).data = it.label
        const t = ie.lastChild!.firstChild as Text
        t.data = itemText(it, FIRST_UNIT)
        els.push(ie)
        if (it.v !== null) { vals.push(t); metres.push(it.v) }
        ge.append(ie)
      }
      grps.append(ge)
    }
    root.append(pe)
  }
  host.append(root)
  let focus = NO_FOCUS
  return {
    step: (p) => {
      const s = p as Step
      if ("unit" in s) { for (let i = 0; i < vals.length; i++) vals[i]!.data = fmt(metres[i]!, s.unit); return }
      if (focus !== NO_FOCUS) els[focus - 1]!.className = itemClass(false)
      els[(focus = s.focus) - 1]!.className = itemClass(true)
    },
    destroy: () => root.remove(),
  }
}

deep.march:
// State at the top, March: App holds the unit as a signal and the focus behind a selector(); Panel > Group > Item
// are real components that run once. The unit is passed down as a prop (the compiler makes props live getters) and the
// selector function is passed as a prop too. Only the measured items read the unit (one per group), so a
// unit step updates only those 200 value text bindings; a focus step
// marks just the old and the new item's class binding. No component runs again and nothing is compared.
import { render, signal, selector } from "march"
import { FIRST_UNIT, NO_FOCUS, fmt, itemClass, type Deep, type Panel, type Group, type Item, type Step } from "./def.ts"
import type { ScenarioApp } from "../core.ts"

type IsOn = (id: number) => boolean
function ItemView(props: { it: Item; unit: string; isOn: IsOn }) {
  const it = props.it, isOn = props.isOn
  return <div class={itemClass(isOn(it.id))}><span class="k">{it.label}</span><b class="v">{it.v === null ? `#${it.id}` : fmt(it.v, props.unit)}</b></div>
}
function GroupView(props: { g: Group; unit: string; isOn: IsOn }) {
  const g = props.g
  return <div class="grp"><h4>{g.title}</h4>{g.items.map((it) => <ItemView it={it} unit={props.unit} isOn={props.isOn} />)}</div>
}
function PanelView(props: { p: Panel; unit: string; isOn: IsOn }) {
  const p = props.p
  return <section class="pnl"><h3>{p.title}</h3><p class="note">{p.note}</p>
    <div class="grps">{p.groups.map((g) => <GroupView g={g} unit={props.unit} isOn={props.isOn} />)}</div></section>
}

export function mount(host: HTMLElement, data: Deep): ScenarioApp {
  const unit = signal(FIRST_UNIT), focus = signal(NO_FOCUS)
  const isOn = selector(focus)
  const dispose = render(() => <div class="deep">{data.panels.map((p) => <PanelView p={p} unit={unit()} isOn={isOn} />)}</div>, host)
  return {
    step: (p) => { const s = p as Step; if ("unit" in s) unit.set(s.unit); else focus.set(s.focus) },
    destroy: dispose,
  }
}

deep.react:
// State at the top, React 19, with the textbook pattern for state at the top: App holds the unit and the focus in
// useState and passes them down as props; Panel, Group and Item are memo components and each child receives only
// what it needs (the focus if it lies inside that child, else -1; an item gets a boolean, and the unit only if it is
// a measured item), so the props stay equal where nothing changed. A focus step re-renders App, then only the old and
// the new item's panel, group and item; the other panels are skipped by memo. A unit step reaches every group, so all
// panels and groups render and are reconciled, and the 200 measured items render again. The unit is a prop, not
// context: context would re-render the same measured items and skip nothing more. Updates run in flushSync.
import { createElement as h, memo, useState } from "react"
import { flushSync } from "react-dom"
import { createRoot } from "react-dom/client"
import { FIRST_UNIT, NO_FOCUS, itemText, itemClass, panelOf, groupOf, type Deep, type Panel, type Group, type Item, type Step } from "./def.ts"
import type { ScenarioApp } from "../core.ts"

const ItemView = memo(function ItemView({ it, unit, on }: { it: Item; unit: string; on: boolean }) {
  return h("div", { className: itemClass(on) }, h("span", { className: "k" }, it.label), h("b", { className: "v" }, itemText(it, unit)))
})
const GroupView = memo(function GroupView({ g, unit, focus }: { g: Group; unit: string; focus: number }) {
  return h("div", { className: "grp" }, h("h4", null, g.title), g.items.map((it) => h(ItemView, { key: it.id, it, unit: it.v === null ? "" : unit, on: it.id === focus })))
})
const PanelView = memo(function PanelView({ p, unit, focus }: { p: Panel; unit: string; focus: number }) {
  return h("section", { className: "pnl" }, h("h3", null, p.title), h("p", { className: "note" }, p.note),
    h("div", { className: "grps" }, p.groups.map((g) => h(GroupView, { key: g.id, g, unit, focus: groupOf(focus) === g.id - 1 ? focus : NO_FOCUS }))))
})

export function mount(host: HTMLElement, data: Deep): ScenarioApp {
  let setUnit: (u: string) => void = () => {}, setFocus: (f: number) => void = () => {}
  const App = () => {
    const [unit, su] = useState(FIRST_UNIT), [focus, sf] = useState(NO_FOCUS)
    setUnit = su; setFocus = sf
    return h("div", { className: "deep" }, data.panels.map((p) => h(PanelView, { key: p.id, p, unit, focus: panelOf(focus) === p.id - 1 ? focus : NO_FOCUS })))
  }
  const root = createRoot(host)
  flushSync(() => root.render(h(App)))
  return {
    step: (p) => { const s = p as Step; flushSync(() => ("unit" in s ? setUnit(s.unit) : setFocus(s.focus))) },
    destroy: () => root.unmount(),
  }
}

deep.preact:
// State at the top, Preact 10: App holds the unit and the focus in its state and passes them down as props; Panel,
// Group and Item are pure components (shouldComponentUpdate with a shallow props check, what memo does) and each child
// receives only what it needs (the focus if it lies inside that child, else -1; an item gets a boolean, and the unit
// only if it is a measured item). A focus step re-renders App and only the old and the new item's panel, group and
// item; a unit step reaches every group, so all panels and groups render and are diffed, and the 200 measured items
// render again. Preact renders in a microtask, before the paint.
import { h, render, Component } from "preact"
import { FIRST_UNIT, NO_FOCUS, itemText, itemClass, panelOf, groupOf, type Deep, type Panel, type Group, type Item, type Step } from "./def.ts"
import type { ScenarioApp } from "../core.ts"

abstract class Pure<P extends object> extends Component<P> {
  override shouldComponentUpdate(next: P) { for (const k in next) if (next[k] !== (this.props as P)[k]) return true; return false }
}
class ItemView extends Pure<{ it: Item; unit: string; on: boolean }> {
  render({ it, unit, on }: { it: Item; unit: string; on: boolean }) {
    return h("div", { class: itemClass(on) }, h("span", { class: "k" }, it.label), h("b", { class: "v" }, itemText(it, unit)))
  }
}
class GroupView extends Pure<{ g: Group; unit: string; focus: number }> {
  render({ g, unit, focus }: { g: Group; unit: string; focus: number }) {
    return h("div", { class: "grp" }, h("h4", null, g.title), g.items.map((it) => h(ItemView, { key: it.id, it, unit: it.v === null ? "" : unit, on: it.id === focus })))
  }
}
class PanelView extends Pure<{ p: Panel; unit: string; focus: number }> {
  render({ p, unit, focus }: { p: Panel; unit: string; focus: number }) {
    return h("section", { class: "pnl" }, h("h3", null, p.title), h("p", { class: "note" }, p.note),
      h("div", { class: "grps" }, p.groups.map((g) => h(GroupView, { key: g.id, g, unit, focus: groupOf(focus) === g.id - 1 ? focus : NO_FOCUS }))))
  }
}

interface AppState { unit: string; focus: number }
export function mount(host: HTMLElement, data: Deep): ScenarioApp {
  let app: App | null = null
  class App extends Component<object, AppState> {
    constructor(p: object) { super(p); this.state = { unit: FIRST_UNIT, focus: NO_FOCUS }; app = this }
    render(_p: object, { unit, focus }: AppState) {
      return h("div", { class: "deep" }, data.panels.map((p) => h(PanelView, { key: p.id, p, unit, focus: panelOf(focus) === p.id - 1 ? focus : NO_FOCUS })))
    }
  }
  render(h(App, null), host)
  return {
    step: (p) => { const s = p as Step; app!.setState("unit" in s ? { unit: s.unit } : { focus: s.focus }) },
    destroy: () => render(null, host),
  }
}

deep.vue:
// ── vue-group.template.html
<div class="grp"><h4>{{ g.title }}</h4><ItemView v-for="it of g.items" :key="it.id" :it="it" :unit="it.v === null ? '' : unit" :on="it.id === focus" /></div>

// ── vue-item.template.html
<div :class="cls(on)"><span class="k">{{ it.label }}</span><b class="v">{{ text(it, unit) }}</b></div>

// ── vue-panel.template.html
<section class="pnl"><h3>{{ p.title }}</h3><p class="note">{{ p.note }}</p><div class="grps"><GroupView v-for="g of p.groups" :key="g.id" :g="g" :unit="unit" :focus="gf(focus, g.id)" /></div></section>

// ── vue.template.html
<div class="deep"><PanelView v-for="p of panels" :key="p.id" :p="p" :unit="s.unit" :focus="pf(s.focus, p.id)" /></div>

// ── vue.ts
// State at the top, Vue 3: App holds the unit and the focus in a reactive object and passes them down as props through
// PanelView > GroupView > ItemView components (templates compiled ahead of time by Vue's compiler: vue*.template.html
// → *.render.gen.js). Vue re-renders a child only when its props changed, and each child receives only the focus it
// needs (the focused id if it lies inside that child, else -1; the item gets a boolean, and the unit only if it is a measured item): a focus step re-renders App
// and the old and the new item's panel, group and item; a unit step changes the props of every panel, group and
// measured item, so they render and are patched. The data itself is plain (markRaw). Vue renders in a microtask, before the paint.
import { createApp, defineComponent, reactive, markRaw } from "vue"
import { render as appRender } from "./vue.render.gen.js"
import { render as panelRender } from "./vue-panel.render.gen.js"
import { render as groupRender } from "./vue-group.render.gen.js"
import { render as itemRender } from "./vue-item.render.gen.js"
import { FIRST_UNIT, NO_FOCUS, itemText, itemClass, panelOf, groupOf, type Deep, type Step } from "./def.ts"
import type { ScenarioApp } from "../core.ts"

const pf = (focus: number, id: number) => (panelOf(focus) === id - 1 ? focus : NO_FOCUS)
const gf = (focus: number, id: number) => (groupOf(focus) === id - 1 ? focus : NO_FOCUS)
export function mount(host: HTMLElement, data: Deep): ScenarioApp {
  const s = reactive({ unit: FIRST_UNIT, focus: NO_FOCUS })
  const panels = markRaw(data.panels)
  const ItemView = defineComponent({ props: { it: { type: Object, required: true }, unit: { type: String, required: true }, on: { type: Boolean, required: true } }, setup: () => ({ text: itemText, cls: itemClass }), render: itemRender })
  const GroupView = defineComponent({ components: { ItemView }, props: { g: { type: Object, required: true }, unit: { type: String, required: true }, focus: { type: Number, required: true } }, render: groupRender })
  const PanelView = defineComponent({ components: { GroupView }, props: { p: { type: Object, required: true }, unit: { type: String, required: true }, focus: { type: Number, required: true } }, setup: () => ({ gf }), render: panelRender })
  const App = defineComponent({ components: { PanelView }, setup: () => ({ s, panels, pf }), render: appRender })
  const app = createApp(App)
  app.mount(host)
  return {
    step: (p) => { const st = p as Step; if ("unit" in st) s.unit = st.unit; else s.focus = st.focus },
    destroy: () => app.unmount(),
  }
}

deep.solid:
// State at the top, SolidJS: App holds the unit as a signal and the focus behind createSelector(); Panel > Group > Item
// are real components that run once. The unit is passed down as a prop (Solid compiles it to a live getter) and the
// selector function is passed as a prop too. Only the measured items read the unit (one per group), so a
// unit step updates only those 200 value text bindings; a focus step
// updates just the old and the new item's class binding. Compiled with babel-preset-solid
// (tools/gen-bench.mjs → solid.gen.js).
import { createSignal, createSelector } from "solid-js"
import { render } from "solid-js/web"
import { FIRST_UNIT, NO_FOCUS, fmt, itemClass } from "./def.ts"

function ItemView(props) {
  const it = props.it, isOn = props.isOn
  return <div class={itemClass(isOn(it.id))}><span class="k">{it.label}</span><b class="v">{it.v === null ? `#${it.id}` : fmt(it.v, props.unit)}</b></div>
}
function GroupView(props) {
  const g = props.g
  return <div class="grp"><h4>{g.title}</h4>{g.items.map((it) => <ItemView it={it} unit={props.unit} isOn={props.isOn} />)}</div>
}
function PanelView(props) {
  const p = props.p
  return <section class="pnl"><h3>{p.title}</h3><p class="note">{p.note}</p>
    <div class="grps">{p.groups.map((g) => <GroupView g={g} unit={props.unit} isOn={props.isOn} />)}</div></section>
}

export function mount(host, data) {
  const [unit, setUnit] = createSignal(FIRST_UNIT), [focus, setFocus] = createSignal(NO_FOCUS)
  const isOn = createSelector(focus)
  const dispose = render(() => <div class="deep">{data.panels.map((p) => <PanelView p={p} unit={unit()} isOn={isOn} />)}</div>, host)
  return { step: (s) => ("unit" in s ? setUnit(s.unit) : setFocus(s.focus)), destroy: dispose }
}

deep.lit:
// State at the top, Lit 3: the unit and the focus are plain values at the top and every step renders the whole tree
// again from the root with them (panel > group > item templates, nested); lit-html compares every part's value and
// touches the DOM only where one changed. The formatted values are computed once per unit (a step that only moves the
// focus reuses them). Templates in compiled form (../lit-tpl.ts), as the CSP refuses HTML strings.
import { render } from "lit/html.js"
import { template, el, child, attr } from "../lit-tpl.ts"
import { FIRST_UNIT, NO_FOCUS, itemText, itemClass, type Deep, type Step } from "./def.ts"
import type { ScenarioApp } from "../core.ts"

export function mount(host: HTMLElement, data: Deep): ScenarioApp {
  const itemT = template(el("div", { class: attr("class") }, el("span", { class: "k" }, child()), el("b", { class: "v" }, child())))
  const groupT = template(el("div", { class: "grp" }, el("h4", {}, child()), child()))
  const panelT = template(el("section", { class: "pnl" }, el("h3", {}, child()), el("p", { class: "note" }, child()), el("div", { class: "grps" }, child())))
  const root = document.createElement("div")
  root.className = "deep"; host.append(root)
  let unit = FIRST_UNIT, focus = NO_FOCUS
  let texts = data.items.map((it) => itemText(it, unit))
  const draw = () => render(data.panels.map((p) => panelT(p.title, p.note,
    p.groups.map((g) => groupT(g.title, g.items.map((it) => itemT(itemClass(it.id === focus), it.label, texts[it.id - 1]))))
  )), root)
  draw()
  return {
    step: (p) => {
      const s = p as Step
      if ("unit" in s) { unit = s.unit; texts = data.items.map((it) => itemText(it, unit)) } else focus = s.focus
      draw()
    },
    destroy: () => { render(null, root); root.remove() },
  }
}

deep.inferno:
// State at the top, Inferno: the unit and the focus are app state passed down through Panel > Group > Item (function
// components). A step renders the app again (render() is synchronous); each level skips its update unless the unit
// changed or the old or new focus is inside it (onComponentShouldUpdate, with def.ts panelOf / groupOf), so a focus
// step re-renders two items and their ancestors, a unit step the 200 measured items.
// Compiled with babel-plugin-inferno (tools/gen-bench.mjs → inferno.gen.js).
import { render } from "inferno"
import { FIRST_UNIT, NO_FOCUS, itemText, itemClass, panelOf, groupOf } from "./def.ts"

function ItemView({ it, unit, on }) {
  return <div className={itemClass(on)}><span className="k">{it.label}</span><b className="v">{itemText(it, unit)}</b></div>
}
function GroupView({ g, unit, focus }) {
  return <div className="grp"><h4>{g.title}</h4>{g.items.map((it) => <ItemView key={it.id} it={it} unit={unit} on={it.id === focus} onComponentShouldUpdate={itemChanged} />)}</div>
}
function PanelView({ p, unit, focus }) {
  return <section className="pnl"><h3>{p.title}</h3><p className="note">{p.note}</p>
    <div className="grps">{p.groups.map((g) => <GroupView key={g.id} g={g} gi={g.id - 1} unit={unit} focus={focus} onComponentShouldUpdate={groupChanged} />)}</div></section>
}
const itemChanged = (a, b) => a.on !== b.on || (a.unit !== b.unit && a.it.v !== null)
const groupChanged = (a, b) => a.unit !== b.unit || (a.focus !== b.focus && (groupOf(a.focus) === a.gi || groupOf(b.focus) === a.gi))
const panelChanged = (a, b) => a.unit !== b.unit || (a.focus !== b.focus && (panelOf(a.focus) === a.pi || panelOf(b.focus) === a.pi))

export function mount(host, data) {
  let unit = FIRST_UNIT, focus = NO_FOCUS
  const draw = () => render(<div className="deep">{data.panels.map((p, k) => <PanelView key={p.id} p={p} pi={k} unit={unit} focus={focus} onComponentShouldUpdate={panelChanged} />)}</div>, host)
  draw()
  return {
    step: (s) => { if ("unit" in s) unit = s.unit; else focus = s.focus; draw() },
    destroy: () => render(null, host),
  }
}

deep.ivi:
// State at the top, ivi: the unit and the focus are app state passed down through Panel > Group > Item components.
// A step updates the app again; each level skips its update unless the unit changed or the old or new focus is inside
// it (the components' areEqual, with def.ts panelOf / groupOf), so a focus step re-renders two items and their
// ancestors, a unit step the 200 measured items. Templates compiled with ivi's template compiler
// (tools/gen-bench.mjs → ivi.gen.js).
import { createRoot, update, component, html } from "ivi"
import { FIRST_UNIT, NO_FOCUS, itemText, itemClass, panelOf, groupOf, type Deep, type Step, type Item, type Group, type Panel } from "./def.ts"
import type { ScenarioApp } from "../core.ts"

interface ItemP { it: Item; unit: string; on: boolean }
interface GroupP { g: Group; unit: string; focus: number }
interface PanelP { p: Panel; pi: number; unit: string; focus: number }
const ItemView = component<ItemP>(() => ({ it, unit, on }) => html`<div class=${itemClass(on)}><span class="k">${it.label}</span><b class="v">${itemText(it, unit)}</b></div>`,
  (a, b) => a.on === b.on && (a.unit === b.unit || a.it.v === null))
const GroupView = component<GroupP>(() => ({ g, unit, focus }) => html`<div class="grp"><h4>${g.title}</h4>${g.items.map((it) => ItemView({ it, unit, on: it.id === focus }))}</div>`,
  (a, b) => a.unit === b.unit && (a.focus === b.focus || (groupOf(a.focus) !== a.g.id - 1 && groupOf(b.focus) !== a.g.id - 1)))
const PanelView = component<PanelP>(() => ({ p, unit, focus }) => html`<section class="pnl"><h3>${p.title}</h3><p class="note">${p.note}</p><div class="grps">${p.groups.map((g) => GroupView({ g, unit, focus }))}</div></section>`,
  (a, b) => a.unit === b.unit && (a.focus === b.focus || (panelOf(a.focus) !== a.pi && panelOf(b.focus) !== a.pi)))

export function mount(host: HTMLElement, data: Deep): ScenarioApp {
  let unit = FIRST_UNIT, focus = NO_FOCUS
  const root = createRoot(host)
  const draw = () => update(root, html`<div class="deep">${data.panels.map((p, pi) => PanelView({ p, pi, unit, focus }))}</div>`)
  draw()
  return {
    step: (s) => { const x = s as Step; if ("unit" in x) unit = x.unit; else focus = x.focus; draw() },
    destroy: () => update(root, null),
  }
}

deep.mithril:
// State at the top, Mithril: the unit and the focus are app state passed down through Panel > Group > Item
// components. One redraw (m.redraw.sync) per step; each level skips its diff unless the unit changed or the old or new
// focus is inside it (onbeforeupdate, with def.ts panelOf / groupOf), so a focus step diffs two items and their
// ancestors, a unit step the 200 measured items.
import m from "mithril"
import { FIRST_UNIT, NO_FOCUS, itemText, itemClass, panelOf, groupOf, type Deep, type Step, type Item, type Group, type Panel } from "./def.ts"
import type { ScenarioApp } from "../core.ts"

const ItemView: m.Component<{ it: Item; unit: string; on: boolean }> = {
  onbeforeupdate: (v, o) => v.attrs.on !== o.attrs.on || (v.attrs.unit !== o.attrs.unit && v.attrs.it.v !== null),
  view: ({ attrs: { it, unit, on } }) => m("div", { class: itemClass(on) }, m("span.k", it.label), m("b.v", itemText(it, unit))),
}
const GroupView: m.Component<{ g: Group; unit: string; focus: number }> = {
  onbeforeupdate: (v, o) => v.attrs.unit !== o.attrs.unit || (v.attrs.focus !== o.attrs.focus && (groupOf(v.attrs.focus) === v.attrs.g.id - 1 || groupOf(o.attrs.focus) === v.attrs.g.id - 1)),
  view: ({ attrs: { g, unit, focus } }) => m("div.grp", m("h4", g.title), g.items.map((it) => m(ItemView, { key: it.id, it, unit, on: it.id === focus }))),
}
const PanelView: m.Component<{ p: Panel; pi: number; unit: string; focus: number }> = {
  onbeforeupdate: (v, o) => v.attrs.unit !== o.attrs.unit || (v.attrs.focus !== o.attrs.focus && (panelOf(v.attrs.focus) === v.attrs.pi || panelOf(o.attrs.focus) === v.attrs.pi)),
  view: ({ attrs: { p, unit, focus } }) => m("section.pnl", m("h3", p.title), m("p.note", p.note), m("div.grps", p.groups.map((g) => m(GroupView, { key: g.id, g, unit, focus })))),
}
export function mount(host: HTMLElement, data: Deep): ScenarioApp {
  let unit = FIRST_UNIT, focus = NO_FOCUS
  m.mount(host, { view: () => m("div.deep", data.panels.map((p, pi) => m(PanelView, { key: p.id, p, pi, unit, focus }))) })
  return {
    step: (s) => { const x = s as Step; if ("unit" in x) unit = x.unit; else focus = x.focus; m.redraw.sync() },
    destroy: () => m.mount(host, null),
  }
}

deep.alpine:
// State at the top, Alpine.js (CSP build): the unit and the focus are reactive at the top; the panel > group > item
// levels are nested x-for templates that read them. Only the measured items read the unit (one per group); every
// item's class reads the focus (Alpine has no selector primitive), so a focus step re-runs every item's class binding
// and writes only the two that changed. Updates run in Alpine's microtask (before the paint).
import Alpine from "@alpinejs/csp"
import { el, start } from "../../apps/alpine-dom.ts"
import { FIRST_UNIT, NO_FOCUS, itemText, itemClass, type Deep, type Step } from "./def.ts"
import type { ScenarioApp } from "../core.ts"

interface State { unit: string; focus: number }
export function mount(host: HTMLElement, data: Deep): ScenarioApp {
  // <div class="deep"><template x-for="p in panels" :key="p.id"><section class="pnl"><h3 x-text="p.title"></h3><p class="note" x-text="p.note"></p>
  //   <div class="grps"><template x-for="g in p.groups" :key="g.id"><div class="grp"><h4 x-text="g.title"></h4>
  //     <template x-for="it in g.items" :key="it.id"><div :class="cls(it.id === focus)"><span class="k" x-text="it.label"></span>
  //       <b class="v" x-text="text(it, it.v === null ? '' : unit)"></b></div></template></div></template></div></section></template></div>
  const item = el("div", { "x-bind:class": "cls(it.id === focus)" }, el("span", { class: "k", "x-text": "it.label" }), el("b", { class: "v", "x-text": "text(it, it.v === null ? '' : unit)" }))
  const group = el("div", { class: "grp" }, el("h4", { "x-text": "g.title" }), el("template", { "x-for": "it in g.items", "x-bind:key": "it.id" }, item))
  const panel = el("section", { class: "pnl" }, el("h3", { "x-text": "p.title" }), el("p", { class: "note", "x-text": "p.note" }),
    el("div", { class: "grps" }, el("template", { "x-for": "g in p.groups", "x-bind:key": "g.id" }, group)))
  const root = el("div", { class: "deep" }, el("template", { "x-for": "p in panels", "x-bind:key": "p.id" }, panel))
  const s = start<State>(host, root, { panels: data.panels, unit: FIRST_UNIT, focus: NO_FOCUS, cls: itemClass, text: itemText } as State)
  return {
    step: (x) => { const st = x as Step; if ("unit" in st) s.unit = st.unit; else s.focus = st.focus },
    destroy: () => { Alpine.destroyTree(root); root.remove() },
  }
}

deep.angular:
// State at the top, Angular: the unit and the focus are signals at the top, passed down through Panel > Group > Item
// (OnPush components). Each item reads the unit only if it is measured, and its focus through a computed() that
// changes only for the item gaining or losing it (a selector made of signals), so a focus step refreshes two item
// views and a unit step the 200 measured ones. Compiled ahead of time with the benchmark app (tools/gen-bench.mjs →
// ../../apps/angular.gen.js).
import { ChangeDetectionStrategy, Component, Input, computed, signal, type OnInit, type Signal } from "@angular/core"
import { mountRoot } from "../angular-host.ts"
import { FIRST_UNIT, NO_FOCUS, itemText, itemClass, type Deep, type Step, type Item, type Group, type Panel } from "./def.ts"
import type { ScenarioApp } from "../core.ts"

@Component({
  selector: "div[dpItem]", changeDetection: ChangeDetectionStrategy.OnPush, host: { "[class]": "cls()" },
  template: `<span class="k">{{ it.label }}</span><b class="v">{{ text() }}</b>`,
})
class ItemView implements OnInit {
  @Input({ required: true }) it!: Item
  @Input({ required: true }) unit!: Signal<string>
  @Input({ required: true }) focus!: Signal<number>
  cls!: Signal<string>
  text!: Signal<string>
  ngOnInit(): void {
    const it = this.it, on = computed(() => this.focus() === it.id)
    this.cls = computed(() => itemClass(on()))
    this.text = it.v === null ? signal(itemText(it, "")) : computed(() => itemText(it, this.unit()))
  }
}

@Component({
  selector: "div[dpGroup]", host: { class: "grp" }, changeDetection: ChangeDetectionStrategy.OnPush, imports: [ItemView],
  template: `<h4>{{ g.title }}</h4>@for (it of g.items; track it.id) {<div dpItem [it]="it" [unit]="unit" [focus]="focus"></div>}`,
})
class GroupView { @Input({ required: true }) g!: Group; @Input({ required: true }) unit!: Signal<string>; @Input({ required: true }) focus!: Signal<number> }

@Component({
  selector: "section[dpPanel]", host: { class: "pnl" }, changeDetection: ChangeDetectionStrategy.OnPush, imports: [GroupView],
  template: `<h3>{{ p.title }}</h3><p class="note">{{ p.note }}</p><div class="grps">@for (g of p.groups; track g.id) {<div dpGroup [g]="g" [unit]="unit" [focus]="focus"></div>}</div>`,
})
class PanelView { @Input({ required: true }) p!: Panel; @Input({ required: true }) unit!: Signal<string>; @Input({ required: true }) focus!: Signal<number> }

@Component({
  selector: "bench-deep", changeDetection: ChangeDetectionStrategy.OnPush, imports: [PanelView],
  template: `<div class="deep">@for (p of panels; track p.id) {<section dpPanel [p]="p" [unit]="unit" [focus]="focus"></section>}</div>`,
})
class DeepView { @Input({ required: true }) panels!: Panel[]; readonly unit = signal(FIRST_UNIT); readonly focus = signal(NO_FOCUS) }

export async function mount(host: HTMLElement, data: Deep): Promise<ScenarioApp> {
  const app = await mountRoot(DeepView, host, "bench-deep", { panels: data.panels })
  const { unit, focus } = app.instance
  return { step: (s) => app.now(() => { const x = s as Step; if ("unit" in x) unit.set(x.unit); else focus.set(x.focus) }), destroy: app.destroy }
}

derived.vanilla:
// Derived values, plain DOM (hand-optimized): a dependency index (field → computed cells that read it) is built once;
// an edit writes the field's text, recomputes only its dependents and writes only the texts and classes that changed.
import { evalComp, compClass, dependents, type Form, type Edit } from "./def.ts"
import type { ScenarioApp } from "../core.ts"

export function mount(host: HTMLElement, data: Form): ScenarioApp {
  const doc = host.ownerDocument
  const f = data.fields.slice(), get = (i: number) => f[i]!, deps = dependents(data)
  const root = doc.createElement("div"), fbox = doc.createElement("div"), cbox = doc.createElement("div")
  root.className = "dv"; fbox.className = "dv-fs"; cbox.className = "dv-cs"
  const ftext: Text[] = [], ctext: Text[] = [], cel: HTMLElement[] = [], cval: number[] = [], ccls: string[] = []
  for (const v of f) {
    const s = doc.createElement("span"), t = doc.createTextNode(String(v))
    s.className = "dv-f"; s.append(t); fbox.append(s); ftext.push(t)
  }
  for (const c of data.comps) {
    const v = evalComp(c, get), cls = compClass(c, v)
    const s = doc.createElement("span"), t = doc.createTextNode(String(v))
    s.className = cls; s.append(t); cbox.append(s)
    ctext.push(t); cel.push(s); cval.push(v); ccls.push(cls)
  }
  root.append(fbox, cbox)
  host.append(root)
  return {
    step: (p) => {
      const e = p as Edit
      if (f[e.i] === e.v) return
      f[e.i] = e.v
      ftext[e.i]!.data = String(e.v)
      for (const k of deps[e.i]!) {
        const c = data.comps[k]!, v = evalComp(c, get)
        if (v === cval[k]) continue
        cval[k] = v; ctext[k]!.data = String(v)
        const cls = compClass(c, v)
        if (cls !== ccls[k]) { ccls[k] = cls; cel[k]!.className = cls }
      }
    },
    destroy: () => root.remove(),
  }
}

derived.march:
// Derived values, March: each field is a signal and each computed cell a computed() reading its fields, so an
// edit re-runs only the computeds that read that field (dependencies are tracked, not declared) and only their bound
// text and class update. The class is a second computed over the value, so it changes only when the flag flips.
import { render, signal, computed } from "march"
import { evalComp, compClass, type Form, type Edit } from "./def.ts"
import type { ScenarioApp } from "../core.ts"

export function mount(host: HTMLElement, data: Form): ScenarioApp {
  const fields = data.fields.map((v) => signal(v))
  const get = (i: number) => fields[i]!()
  const comps = data.comps.map((c) => {
    const value = computed(() => evalComp(c, get))
    return { value, cls: computed(() => compClass(c, value())) }
  })
  const dispose = render(() => <div class="dv">
    <div class="dv-fs">{fields.map((f) => <span class="dv-f">{f()}</span>)}</div>
    <div class="dv-cs">{comps.map((c) => <span class={c.cls()}>{c.value()}</span>)}</div>
  </div>, host)
  return {
    step: (p) => { const e = p as Edit; fields[e.i]!.set(e.v) },
    destroy: dispose,
  }
}

derived.react:
// Derived values, React 19: the fields live in a small external store with one listener set per field. Each field
// cell and each computed cell is a memo component reading the store through useSyncExternalStore; a computed cell
// subscribes only to its own fields and its snapshot is the derived number (a selector), so an edit re-renders the
// edited field and only the computed cells whose value changed; the form component itself never renders again.
// (Lifting the 200 fields into one useState with useMemo per cell would re-render and diff all 700 cells per edit.)
// Updates run in flushSync.
import { createElement as h, memo, useSyncExternalStore } from "react"
import { flushSync } from "react-dom"
import { createRoot } from "react-dom/client"
import { evalComp, compClass, type Form, type Edit } from "./def.ts"
import type { ScenarioApp } from "../core.ts"

export function mount(host: HTMLElement, data: Form): ScenarioApp {
  const f = data.fields.slice(), get = (i: number) => f[i]!
  const subs: Set<() => void>[] = f.map(() => new Set())
  const listen = (ids: number[]) => (cb: () => void) => { for (const i of ids) subs[i]!.add(cb); return () => { for (const i of ids) subs[i]!.delete(cb) } }
  const fieldSub = f.map((_, i) => listen([i])), compSub = data.comps.map((c) => listen([...new Set(c.deps)]))
  const Field = memo(function Field({ i }: { i: number }) {
    const v = useSyncExternalStore(fieldSub[i]!, () => f[i]!)
    return h("span", { className: "dv-f" }, v)
  })
  const Computed = memo(function Computed({ k }: { k: number }) {
    const c = data.comps[k]!
    const v = useSyncExternalStore(compSub[k]!, () => evalComp(c, get))
    return h("span", { className: compClass(c, v) }, v)
  })
  const App = () => h("div", { className: "dv" },
    h("div", { className: "dv-fs" }, f.map((_, i) => h(Field, { key: i, i }))),
    h("div", { className: "dv-cs" }, data.comps.map((_, k) => h(Computed, { key: k, k }))))
  const root = createRoot(host)
  flushSync(() => root.render(h(App)))
  return {
    step: (p) => flushSync(() => {
      const e = p as Edit
      f[e.i] = e.v
      for (const cb of subs[e.i]!) cb()
    }),
    destroy: () => root.unmount(),
  }
}

derived.preact:
// Derived values, Preact 10: the fields live in a small store with one listener set per field. Each field cell and
// each computed cell is a class component that subscribes only to the fields it reads and keeps the derived number
// in its state; an edit calls setState on those components, and shouldComponentUpdate skips the ones whose value did
// not change (the form component never renders again). Preact renders in a microtask, before the paint.
import { h, render, Component } from "preact"
import { evalComp, compClass, type Form, type Edit } from "./def.ts"
import type { ScenarioApp } from "../core.ts"

export function mount(host: HTMLElement, data: Form): ScenarioApp {
  const f = data.fields.slice(), get = (i: number) => f[i]!
  const subs: Set<() => void>[] = f.map(() => new Set())
  abstract class Cell<P> extends Component<P, { v: number }> {
    abstract ids(): number[]
    abstract read(): number
    private on = () => this.setState({ v: this.read() })
    override componentDidMount() { for (const i of this.ids()) subs[i]!.add(this.on) }
    override componentWillUnmount() { for (const i of this.ids()) subs[i]!.delete(this.on) }
    override shouldComponentUpdate(_p: P, s: { v: number }) { return s.v !== this.state.v }
  }
  class Field extends Cell<{ i: number }> {
    constructor(p: { i: number }) { super(p); this.state = { v: this.read() } }
    ids() { return [this.props.i] }
    read() { return f[this.props.i]! }
    render() { return h("span", { class: "dv-f" }, this.state.v) }
  }
  class Computed extends Cell<{ k: number }> {
    constructor(p: { k: number }) { super(p); this.state = { v: this.read() } }
    ids() { return [...new Set(data.comps[this.props.k]!.deps)] }
    read() { return evalComp(data.comps[this.props.k]!, get) }
    render() { return h("span", { class: compClass(data.comps[this.props.k]!, this.state.v) }, this.state.v) }
  }
  render(h("div", { class: "dv" },
    h("div", { class: "dv-fs" }, f.map((_, i) => h(Field, { key: i, i }))),
    h("div", { class: "dv-cs" }, data.comps.map((_, k) => h(Computed, { key: k, k })))), host)
  return {
    step: (p) => {
      const e = p as Edit
      f[e.i] = e.v
      for (const cb of subs[e.i]!) cb()
    },
    destroy: () => render(null, host),
  }
}

derived.vue:
// ── vue-comp.template.html
<span :class="cls">{{ value }}</span>

// ── vue-field.template.html
<span class="dv-f">{{ f[i] }}</span>

// ── vue.template.html
<div class="dv">
  <div class="dv-fs"><FieldCell v-for="i of fieldIds" :key="i" :i="i" /></div>
  <div class="dv-cs"><CompCell v-for="k of compIds" :key="k" :k="k" /></div>
</div>

// ── vue.ts
// Derived values, Vue 3: the fields are one reactive array and each computed cell is a computed() reading its fields
// (Vue tracks which array indexes it read), plus a computed class over the value. Each field and each computed cell is
// its own small component (templates compiled ahead of time by Vue's compiler: vue*.template.html → *.render.gen.js),
// so an edit re-renders only the edited field and the computed cells whose value changed; the form does not render
// again. Vue renders in a microtask, before the paint.
import { createApp, defineComponent, reactive, computed, markRaw } from "vue"
import { render as formRender } from "./vue.render.gen.js"
import { render as fieldRender } from "./vue-field.render.gen.js"
import { render as compRender } from "./vue-comp.render.gen.js"
import { evalComp, compClass, type Form, type Edit } from "./def.ts"
import type { ScenarioApp } from "../core.ts"

export function mount(host: HTMLElement, data: Form): ScenarioApp {
  const f = reactive(data.fields.slice())
  const get = (i: number) => f[i]!
  const comps = markRaw(data.comps.map((c) => {
    const value = computed(() => evalComp(c, get))
    return { value, cls: computed(() => compClass(c, value.value)) }
  }))
  const FieldCell = defineComponent({ props: { i: { type: Number, required: true } }, setup: () => ({ f }), render: fieldRender })
  const CompCell = defineComponent({ props: { k: { type: Number, required: true } }, setup: (p) => ({ value: comps[p.k]!.value, cls: comps[p.k]!.cls }), render: compRender })
  const fieldIds = markRaw(data.fields.map((_, i) => i)), compIds = markRaw(data.comps.map((_, k) => k))
  const App = defineComponent({ components: { FieldCell, CompCell }, setup: () => ({ fieldIds, compIds }), render: formRender })
  const app = createApp(App)
  app.mount(host)
  return {
    step: (p) => { const e = p as Edit; f[e.i] = e.v },
    destroy: () => app.unmount(),
  }
}

derived.solid:
// Derived values, SolidJS: each field is a signal and each computed cell a createMemo reading its fields (plus a memo
// for the class), so an edit re-runs only the memos that read that field and Solid updates only their bound text and
// class. Compiled with babel-preset-solid (tools/gen-bench.mjs → solid.gen.js).
import { createSignal, createMemo } from "solid-js"
import { render } from "solid-js/web"
import { evalComp, compClass } from "./def.ts"

export function mount(host, data) {
  const fields = data.fields.map((v) => createSignal(v))
  const get = (i) => fields[i][0]()
  const dispose = render(() => {
    const comps = data.comps.map((c) => { const value = createMemo(() => evalComp(c, get)); return { value, cls: createMemo(() => compClass(c, value())) } })
    return (
      <div class="dv">
        <div class="dv-fs">{fields.map(([v]) => <span class="dv-f">{v()}</span>)}</div>
        <div class="dv-cs">{comps.map((c) => <span class={c.cls()}>{c.value()}</span>)}</div>
      </div>
    )
  }, host)
  return {
    step: (e) => fields[e.i][1](e.v),
    destroy: dispose,
  }
}

derived.lit:
// Derived values, Lit 3: Lit has no derived state, so the app memoizes: a dependency index (field → computed cells that
// read it) marks the edited field's dependents dirty, and render() recomputes only those before a render() of the
// whole form. lit-html then walks all 700 cells' values and touches the DOM only where a value changed (no virtual
// DOM, but a value check per cell). Cell templates in compiled form (../lit-tpl.ts), as the CSP refuses HTML strings.
import { render } from "lit/html.js"
import { template, el, attr, child } from "../lit-tpl.ts"
import { evalComp, compClass, dependents, type Form, type Edit } from "./def.ts"
import type { ScenarioApp } from "../core.ts"

export function mount(host: HTMLElement, data: Form): ScenarioApp {
  const field = template(el("span", { class: "dv-f" }, child()))
  const cell = template(el("span", { class: attr("class") }, child()))
  const f = data.fields.slice(), get = (i: number) => f[i]!, deps = dependents(data)
  const value = data.comps.map((c) => evalComp(c, get)), cls = data.comps.map((c, k) => compClass(c, value[k]!))
  let dirty: number[] = []
  const root = document.createElement("div"), fbox = document.createElement("div"), cbox = document.createElement("div")
  root.className = "dv"; fbox.className = "dv-fs"; cbox.className = "dv-cs"
  root.append(fbox, cbox); host.append(root)
  const draw = () => {
    for (const k of dirty) { const c = data.comps[k]!; value[k] = evalComp(c, get); cls[k] = compClass(c, value[k]!) }
    dirty = []
    render(f.map((v) => field(v)), fbox)
    render(value.map((v, k) => cell(cls[k], v)), cbox)
  }
  draw()
  return {
    step: (p) => { const e = p as Edit; f[e.i] = e.v; dirty = deps[e.i]!; draw() },
    destroy: () => { render(null, fbox); render(null, cbox); root.remove() },
  }
}

derived.inferno:
// Derived values, Inferno: Inferno has no derived state, so the app keeps a dependency index (field → computed cells
// that read it, def.ts dependents()). Every field and computed cell is a small class component that registers
// itself; an edit sets the field, recomputes only its dependents and calls forceUpdate() (synchronous in Inferno) on
// the field and on each computed cell whose value changed. Compiled with babel-plugin-inferno (tools/gen-bench.mjs →
// inferno.gen.js).
import { render, Component } from "inferno"
import { evalComp, compClass, dependents } from "./def.ts"

export function mount(host, data) {
  const f = data.fields.slice(), deps = dependents(data), get = (i) => f[i]
  const fieldViews = [], compViews = []
  class Field extends Component {
    constructor(props) { super(props); fieldViews[props.i] = this }
    render() { return <span className="dv-f">{f[this.props.i]}</span> }
  }
  class Comp extends Component {
    constructor(props) { super(props); this.v = evalComp(props.c, get); compViews[props.k] = this }
    refresh() { const v = evalComp(this.props.c, get); if (v !== this.v) { this.v = v; this.forceUpdate() } }
    render() { return <span className={compClass(this.props.c, this.v)}>{this.v}</span> }
  }
  render(
    <div className="dv">
      <div className="dv-fs">{f.map((_, i) => <Field i={i} />)}</div>
      <div className="dv-cs">{data.comps.map((c, k) => <Comp c={c} k={k} />)}</div>
    </div>, host)
  return {
    step: (e) => { f[e.i] = e.v; fieldViews[e.i].forceUpdate(); for (const k of deps[e.i]) compViews[k].refresh() },
    destroy: () => render(null, host),
  }
}

derived.ivi:
// Derived values, ivi: ivi has no derived state, so the app keeps a dependency index (field → computed cells that read
// it, def.ts dependents()). Fields and computed cells are stateful components that register an invalidate; an edit
// sets the field, recomputes only its dependents and invalidates the field and each computed cell whose value
// changed (ivi updates them in a microtask, before the paint). Templates compiled with ivi's template compiler
// (tools/gen-bench.mjs → ivi.gen.js).
import { createRoot, update, component, invalidate, html } from "ivi"
import { evalComp, compClass, dependents, type Form, type Edit, type Comp } from "./def.ts"
import type { ScenarioApp } from "../core.ts"

export function mount(host: HTMLElement, data: Form): ScenarioApp {
  const f = data.fields.slice(), deps = dependents(data), get = (i: number) => f[i]!
  const fieldInv: (() => void)[] = [], compRefresh: (() => void)[] = []
  const Field = component<number>((c) => (i) => { fieldInv[i] ??= () => invalidate(c); return html`<span class="dv-f">${f[i]}</span>` }, () => true)
  const Cell = component<{ c: Comp; k: number }>((ctx) => {
    let v = NaN
    return ({ c, k }) => {
      if (Number.isNaN(v)) { v = evalComp(c, get); compRefresh[k] = () => { const n = evalComp(c, get); if (n !== v) { v = n; invalidate(ctx) } } }
      return html`<span class=${compClass(c, v)}>${v}</span>`
    }
  }, () => true)
  const root = createRoot(host)
  update(root, html`<div class="dv"><div class="dv-fs">${f.map((_, i) => Field(i))}</div><div class="dv-cs">${data.comps.map((c, k) => Cell({ c, k }))}</div></div>`)
  return {
    step: (p) => { const e = p as Edit; f[e.i] = e.v; fieldInv[e.i]!(); for (const k of deps[e.i]!) compRefresh[k]!() },
    destroy: () => update(root, null),
  }
}

derived.mithril:
// Derived values, Mithril: Mithril has no derived state, so the app memoizes: a dependency index (field → computed
// cells that read it, def.ts dependents()) recomputes only the edited field's dependents, then one redraw
// (m.redraw.sync) of the whole form; each cell component skips its diff unless its value changed (onbeforeupdate).
import m from "mithril"
import { evalComp, compClass, dependents, type Form, type Edit } from "./def.ts"
import type { ScenarioApp } from "../core.ts"

const Cell: m.Component<{ cls: string; v: number }> = {
  onbeforeupdate: (v, old) => v.attrs.v !== old.attrs.v || v.attrs.cls !== old.attrs.cls,
  view: ({ attrs }) => m("span", { class: attrs.cls }, attrs.v),
}
export function mount(host: HTMLElement, data: Form): ScenarioApp {
  const f = data.fields.slice(), deps = dependents(data), get = (i: number) => f[i]!
  const vals = data.comps.map((c) => evalComp(c, get))
  m.mount(host, { view: () => m("div.dv",
    m("div.dv-fs", f.map((v) => m(Cell, { cls: "dv-f", v }))),
    m("div.dv-cs", data.comps.map((c, k) => m(Cell, { cls: compClass(c, vals[k]!), v: vals[k]! })))) })
  return {
    step: (p) => {
      const e = p as Edit
      f[e.i] = e.v
      for (const k of deps[e.i]!) vals[k] = evalComp(data.comps[k]!, get)
      m.redraw.sync()
    },
    destroy: () => m.mount(host, null),
  }
}

derived.alpine:
// Derived values, Alpine.js (CSP build): the fields are reactive; each computed cell's x-text and class call a method
// that reads only its own fields, so Alpine's reactivity (Vue's, inside Alpine) re-runs just the bindings of the edited
// field's dependents, in Alpine's microtask (before the paint).
import Alpine from "@alpinejs/csp"
import { el, start } from "../../apps/alpine-dom.ts"
import { evalComp, compClass, type Form, type Edit } from "./def.ts"
import type { ScenarioApp } from "../core.ts"

export function mount(host: HTMLElement, data: Form): ScenarioApp {
  // <div class="dv"><div class="dv-fs"><template x-for="(v, i) in f" :key="i"><span class="dv-f" x-text="v"></span></template></div>
  //   <div class="dv-cs"><template x-for="(c, k) in comps" :key="k"><span :class="cls(k)" x-text="val(k)"></span></template></div></div>
  const root = el("div", { class: "dv" },
    el("div", { class: "dv-fs" }, el("template", { "x-for": "(v, i) in f", "x-bind:key": "i" }, el("span", { class: "dv-f", "x-text": "v" }))),
    el("div", { class: "dv-cs" }, el("template", { "x-for": "(c, k) in comps", "x-bind:key": "k" }, el("span", { "x-bind:class": "cls(k)", "x-text": "val(k)" }))))
  const s = start(host, root, {
    f: data.fields.slice(), comps: data.comps,
    val(k: number): number { return evalComp(data.comps[k]!, (i) => this.f[i]!) },
    cls(k: number): string { return compClass(data.comps[k]!, this.val(k)) },
  })
  return {
    step: (p) => { const e = p as Edit; s.f[e.i] = e.v },
    destroy: () => { Alpine.destroyTree(root); root.remove() },
  }
}

derived.angular:
// Derived values, Angular: every field is a signal and every computed cell a computed() reading its fields (and a
// computed() for its class), so an edit re-runs only the computeds that read that field and refreshes only the views
// that read them. Compiled ahead of time with the benchmark app (tools/gen-bench.mjs → ../../apps/angular.gen.js).
import { ChangeDetectionStrategy, Component, Input, computed, signal, type Signal, type WritableSignal } from "@angular/core"
import { mountRoot } from "../angular-host.ts"
import { evalComp, compClass, type Form, type Edit } from "./def.ts"
import type { ScenarioApp } from "../core.ts"

interface Cell { value: Signal<number>; cls: Signal<string> }

@Component({
  selector: "bench-derived", changeDetection: ChangeDetectionStrategy.OnPush,
  template: `<div class="dv"><div class="dv-fs">@for (f of fields; track $index) {<span class="dv-f">{{ f() }}</span>}</div><div class="dv-cs">@for (c of cells; track $index) {<span [class]="c.cls()">{{ c.value() }}</span>}</div></div>`,
})
class Derived { @Input({ required: true }) fields!: WritableSignal<number>[]; @Input({ required: true }) cells!: Cell[] }

export async function mount(host: HTMLElement, data: Form): Promise<ScenarioApp> {
  const fields = data.fields.map((v) => signal(v)), get = (i: number) => fields[i]!()
  const cells: Cell[] = data.comps.map((c) => { const value = computed(() => evalComp(c, get)); return { value, cls: computed(() => compClass(c, value())) } })
  const app = await mountRoot(Derived, host, "bench-derived", { fields, cells })
  return {
    step: (p) => app.now(() => { const e = p as Edit; fields[e.i]!.set(e.v) }),
    destroy: app.destroy,
  }
}

grid.vanilla:
// Data list, plain DOM (hand-optimized): rows are cloned from one prototype and cached by record, made only when a
// record first becomes visible; the filtered and the sorted view are recomputed only when their inputs change; the
// list is reconciled by key (rows that left are removed, the kept and new rows are put in order, a row already in
// place is not touched); a selection toggle writes one row's class and the summary keeps a running count and total.
import { CATS, SEL, matches, compare, fmtPrice, summary, type Rec, type Act, type Key } from "./def.ts"
import type { ScenarioApp } from "../core.ts"

export function mount(host: HTMLElement, data: Rec[]): ScenarioApp {
  const doc = host.ownerDocument
  const sum = doc.createElement("p"), table = doc.createElement("table"), tbody = doc.createElement("tbody")
  sum.className = "gsum"; sum.append(""); table.className = "bt"; table.append(tbody)
  const proto = doc.createElement("tr")
  for (const c of ["id", "nm", "cat", "px", "st"]) { const td = doc.createElement("td"); td.className = c; td.append(""); proto.append(td) }
  const rows: (HTMLTableRowElement | undefined)[] = new Array(data.length)
  const rowOf = (r: Rec): HTMLTableRowElement => {
    let tr = rows[r.i]
    if (tr) return tr
    tr = proto.cloneNode(true) as HTMLTableRowElement
    const td = tr.cells
    ;(td[0]!.firstChild as Text).data = String(r.id)
    ;(td[1]!.firstChild as Text).data = r.name
    ;(td[2]!.firstChild as Text).data = CATS[r.cat]!
    ;(td[3]!.firstChild as Text).data = fmtPrice(r.price)
    ;(td[4]!.firstChild as Text).data = String(r.stock)
    if (sel[r.i]) tr.className = SEL
    return (rows[r.i] = tr)
  }
  let q = "", key: Key = "id", dir: 1 | -1 = 1, count = 0, total = 0
  const cats = CATS.map(() => true), sel = new Array<boolean>(data.length).fill(false)
  let filtered: Rec[] = [], view: Rec[] = [], shown: Rec[] = []
  const refilter = () => { filtered = data.filter((r) => matches(r, q, cats)) }
  const resort = () => { view = filtered.slice().sort(compare(key, dir)) }
  // keyed reconciliation: remove rows no longer shown, then walk the new order, inserting only rows not already in place
  const patch = () => {
    const next = new Uint8Array(data.length)
    for (const r of view) next[r.i] = 1
    for (const r of shown) if (!next[r.i]) rows[r.i]!.remove()
    let cur = tbody.firstChild
    for (const r of view) {
      const tr = rowOf(r)
      if (tr === cur) cur = cur.nextSibling
      else tbody.insertBefore(tr, cur)
    }
    shown = view
  }
  const setSel = (i: number, on: boolean) => {
    if (sel[i] === on) return
    sel[i] = on
    count += on ? 1 : -1
    total += on ? data[i]!.price : -data[i]!.price
    const tr = rows[i]
    if (tr) tr.className = on ? SEL : ""
  }
  const writeSum = () => { (sum.firstChild as Text).data = summary(view.length, count, total) }
  refilter(); resort(); patch(); writeSum()
  host.append(sum, table)
  return {
    step: (p) => {
      const a = p as Act
      if (a.t === "q" || a.t === "cat") {
        if (a.t === "q") q = a.q
        else cats[a.c] = a.on
        refilter(); resort(); patch()
      } else if (a.t === "sort") { key = a.key; dir = a.dir; resort(); patch() }
      else if (a.t === "sel") setSel(a.i, a.on)
      else if (a.t === "all") for (const r of view) setSel(r.i, true)
      else for (let i = 0; i < sel.length; i++) if (sel[i]) setSel(i, false)
      writeSum()
    },
    destroy: () => { sum.remove(); table.remove() },
  }
}

grid.march:
// Data list, March: the query, categories and sort are signals; the filtered list and the sorted view are two
// computed values (a sort change does not filter again); a keyed <For> reuses rows by id and moves the fewest. Each
// record has its own selection signal, so a toggle wakes one row's class binding and the summary, not the list.
import { render, signal, computed, batch, For } from "march"
import { CATS, SEL, matches, compare, fmtPrice, summary, type Rec, type Act, type Key } from "./def.ts"
import type { ScenarioApp } from "../core.ts"

export function mount(host: HTMLElement, data: Rec[]): ScenarioApp {
  const sel = data.map(() => signal(false))
  let $q = ""
  let $cats: boolean[] = CATS.map(() => true)
  let $key: Key = "id"
  let $dir: 1 | -1 = 1
  let $count = 0
  let $total = 0
  const filtered = computed(() => { const q = $q, cats = $cats; return data.filter((r) => matches(r, q, cats)) })
  const view = computed(() => filtered().slice().sort(compare($key, $dir)))
  const setSel = (i: number, on: boolean) => {
    const s = sel[i]!
    if (s.peek() === on) return
    s.set(on)
    $count += on ? 1 : -1
    $total += on ? data[i]!.price : -data[i]!.price
  }
  const dispose = render(() => <div>
    <p class="gsum">{summary(view().length, $count, $total)}</p>
    <table class="bt"><tbody>
      <For each={view()} key="id">{(r) => <tr class={sel[r().i]!() ? SEL : ""}>
        <td class="id">{r().id}</td><td class="nm">{r().name}</td><td class="cat">{CATS[r().cat]}</td>
        <td class="px">{fmtPrice(r().price)}</td><td class="st">{r().stock}</td>
      </tr>}</For>
    </tbody></table>
  </div>, host)
  return {
    step: (p) => batch(() => {
      const a = p as Act
      if (a.t === "q") $q = a.q
      else if (a.t === "cat") { const c = $cats.slice(); c[a.c] = a.on; $cats = c }
      else if (a.t === "sort") { $key = a.key; $dir = a.dir }
      else if (a.t === "sel") setSel(a.i, a.on)
      else if (a.t === "all") for (const r of view.peek()) setSel(r.i, true)
      else for (let i = 0; i < sel.length; i++) setSel(i, false)
    }),
    destroy: dispose,
  }
}

grid.react:
// Data list, React 19, with the patterns React recommends: one useReducer state (query, categories, sort, selection
// as an immutable Set, running count and total), the filtered list and the sorted view in two useMemo, and memo rows
// with a `selected` boolean prop. A selection toggle renders the list component again (2.000 row elements made and
// compared), but only the toggled memo row renders; a filter or sort change is a keyed list diff. Updates run in
// flushSync.
import { createElement as h, memo, useMemo, useReducer, useLayoutEffect } from "react"
import { flushSync } from "react-dom"
import { createRoot } from "react-dom/client"
import { CATS, SEL, matches, compare, fmtPrice, summary, type Rec, type Act, type Key } from "./def.ts"
import type { ScenarioApp } from "../core.ts"

interface State { q: string; cats: boolean[]; key: Key; dir: 1 | -1; sel: ReadonlySet<number>; count: number; total: number }
/** The app's own action: "all" arrives with the visible records (the reducer does not see the memoized view). */
type Do = Exclude<Act, { t: "all" }> | { t: "all"; view: Rec[] }

export function mount(host: HTMLElement, data: Rec[]): ScenarioApp {
  const reduce = (s: State, a: Do): State => {
    switch (a.t) {
      case "q": return { ...s, q: a.q }
      case "cat": { const cats = s.cats.slice(); cats[a.c] = a.on; return { ...s, cats } }
      case "sort": return { ...s, key: a.key, dir: a.dir }
      case "sel": {
        if (s.sel.has(a.i) === a.on) return s
        const sel = new Set(s.sel), price = data[a.i]!.price
        if (a.on) sel.add(a.i); else sel.delete(a.i)
        return { ...s, sel, count: s.count + (a.on ? 1 : -1), total: s.total + (a.on ? price : -price) }
      }
      case "all": {
        const sel = new Set(s.sel)
        let { count, total } = s
        for (const r of a.view) if (!sel.has(r.i)) { sel.add(r.i); count++; total += r.price }
        return { ...s, sel, count, total }
