    const filtered = useMemo(() => data.filter((r) => matches(r, s.q, s.cats)), [s.q, s.cats])
    const view = useMemo(() => filtered.slice().sort(compare(s.key, s.dir)), [filtered, s.key, s.dir])
    useLayoutEffect(() => { api.send = send; api.view = view })
