  const root = createRoot(host)
  flushSync(() => root.render(h(App)))
  return {
    step: (p) => {
      const a = p as Act
      flushSync(() => api.send!(a.t === "all" ? { t: "all", view: api.view } : a))
    },
    destroy: () => root.unmount(),
  }
}

grid.preact:
// Data list, Preact 10, the same pattern as React: one useReducer state (query, categories, sort, selection as an
// immutable Set, running count and total), the filtered list and the sorted view in two useMemo, and memo rows with a
// `selected` boolean prop. A selection toggle renders the list component again, only the toggled memo row renders; a
// filter or sort change is a keyed list diff. Preact renders in a microtask, before the paint.
import { h, render } from "preact"
import { memo } from "preact/compat"
import { useMemo, useReducer, useLayoutEffect } from "preact/hooks"
import { CATS, SEL, matches, compare, fmtPrice, summary, type Rec, type Act, type Key } from "./def.ts"
import type { ScenarioApp } from "../core.ts"

interface State { q: string; cats: boolean[]; key: Key; dir: 1 | -1; sel: ReadonlySet<number>; count: number; total: number }
/** The app's own action: "all" arrives with the visible records (the reducer does not see the memoized view). */
type Do = Exclude<Act, { t: "all" }> | { t: "all"; view: Rec[] }

export function mount(host: HTMLElement, data: Rec[]): ScenarioApp {
  const reduce = (s: State, a: Do): State => {
    switch (a.t) {
      case "q": return { ...s, q: a.q }
      case "cat": { const cats = s.cats.slice(); cats[a.c] = a.on; return { ...s, cats } }
      case "sort": return { ...s, key: a.key, dir: a.dir }
      case "sel": {
        if (s.sel.has(a.i) === a.on) return s
        const sel = new Set(s.sel), price = data[a.i]!.price
        if (a.on) sel.add(a.i); else sel.delete(a.i)
        return { ...s, sel, count: s.count + (a.on ? 1 : -1), total: s.total + (a.on ? price : -price) }
      }
      case "all": {
        const sel = new Set(s.sel)
        let { count, total } = s
        for (const r of a.view) if (!sel.has(r.i)) { sel.add(r.i); count++; total += r.price }
        return { ...s, sel, count, total }
      }
      case "none": return { ...s, sel: new Set(), count: 0, total: 0 }
    }
  }
  const init: State = { q: "", cats: CATS.map(() => true), key: "id", dir: 1, sel: new Set(), count: 0, total: 0 }
  const api: { send?: (a: Do) => void; view: Rec[] } = { view: [] }
  const Row = memo(function Row({ r, selected }: { r: Rec; selected: boolean }) {
    return h("tr", { class: selected ? SEL : "" },
      h("td", { class: "id" }, r.id), h("td", { class: "nm" }, r.name), h("td", { class: "cat" }, CATS[r.cat]),
      h("td", { class: "px" }, fmtPrice(r.price)), h("td", { class: "st" }, r.stock))
  })
  function App() {
    const [s, send] = useReducer(reduce, init)
    const filtered = useMemo(() => data.filter((r) => matches(r, s.q, s.cats)), [s.q, s.cats])
    const view = useMemo(() => filtered.slice().sort(compare(s.key, s.dir)), [filtered, s.key, s.dir])
    useLayoutEffect(() => { api.send = send; api.view = view })
    return h("div", null,
      h("p", { class: "gsum" }, summary(view.length, s.count, s.total)),
      h("table", { class: "bt" }, h("tbody", null, view.map((r) => h(Row, { key: r.id, r, selected: s.sel.has(r.i) })))))
  }
  render(h(App, null), host)
  return {
    step: (p) => { const a = p as Act; api.send!(a.t === "all" ? { t: "all", view: api.view } : a) },
    destroy: () => render(null, host),
  }
}

grid.vue:
// ── vue-row.template.html
<tr :class="sel[r.i] ? 'sel' : ''"><td class="id">{{ r.id }}</td><td class="nm">{{ r.name }}</td><td class="cat">{{ cats[r.cat] }}</td><td class="px">{{ fmt(r.price) }}</td><td class="st">{{ r.stock }}</td></tr>

// ── vue-sum.template.html
<p class="gsum">{{ text(n, s.count, s.total) }}</p>

// ── vue.template.html
<div><GridSum :n="view.length" :s="st" /><table class="bt"><tbody>
  <GridRow v-for="r of view" :key="r.id" :r="r" :sel="sel" />
</tbody></table></div>

// ── vue.ts
// Data list, Vue 3: the query, categories, sort and the running selection count and total live in one reactive
// object; the filtered list and the sorted view are two computed values; a keyed v-for renders one row component per
// record (templates compiled ahead of time: vue*.template.html → *.render.gen.js). Selection is a reactive array of
// flags that each row component reads for its own record, and the summary is its own component, so a toggle
// re-renders one row and the summary, not the list. Vue renders in a microtask, before the paint.
import { createApp, defineComponent, reactive, computed, markRaw } from "vue"
import { render as listRender } from "./vue.render.gen.js"
import { render as rowRender } from "./vue-row.render.gen.js"
import { render as sumRender } from "./vue-sum.render.gen.js"
import { CATS, matches, compare, fmtPrice, summary, type Rec, type Act, type Key } from "./def.ts"
import type { ScenarioApp } from "../core.ts"

export function mount(host: HTMLElement, data: Rec[]): ScenarioApp {
  const recs = markRaw(data.map((r) => markRaw(r)))
  const st = reactive({ q: "", cats: CATS.map(() => true), key: "id" as Key, dir: 1 as 1 | -1, count: 0, total: 0 })
  const sel = reactive(new Array<boolean>(data.length).fill(false))
  const filtered = computed(() => { const q = st.q, cats = st.cats.slice(); return markRaw(recs.filter((r) => matches(r, q, cats))) })
  const view = computed(() => markRaw(filtered.value.slice().sort(compare(st.key, st.dir))))
  const setSel = (i: number, on: boolean) => {
    if (sel[i] === on) return
    sel[i] = on
    st.count += on ? 1 : -1
    st.total += on ? data[i]!.price : -data[i]!.price
  }
  const GridRow = defineComponent({ props: { r: { type: Object, required: true }, sel: { type: Array, required: true } }, setup: () => ({ cats: CATS, fmt: fmtPrice }), render: rowRender })
  const GridSum = defineComponent({ props: { n: { type: Number, required: true }, s: { type: Object, required: true } }, setup: () => ({ text: summary }), render: sumRender })
  const App = defineComponent({ components: { GridRow, GridSum }, setup: () => ({ view, st, sel }), render: listRender })
  const app = createApp(App)
  app.mount(host)
  return {
    step: (p) => {
      const a = p as Act
      if (a.t === "q") st.q = a.q
      else if (a.t === "cat") st.cats[a.c] = a.on
      else if (a.t === "sort") { st.key = a.key; st.dir = a.dir }
      else if (a.t === "sel") setSel(a.i, a.on)
      else if (a.t === "all") for (const r of view.value) setSel(r.i, true)
      else for (let i = 0; i < sel.length; i++) setSel(i, false)
    },
    destroy: () => app.unmount(),
  }
}

grid.solid:
// Data list, SolidJS: the query, categories and sort are signals; the filtered list and the sorted view are two
// createMemo; a keyed <For> reuses rows by record. Each record has its own selection signal, so a toggle wakes one
// row's class binding and the summary, not the list. Compiled with babel-preset-solid (tools/gen-bench.mjs →
// solid.gen.js).
import { createSignal, createMemo, batch } from "solid-js"
import { render, For } from "solid-js/web"
import { CATS, SEL, matches, compare, fmtPrice, summary } from "./def.ts"

export function mount(host, data) {
  let step
  const dispose = render(() => {
    const sel = data.map(() => createSignal(false))
    const [q, setQ] = createSignal(""), [cats, setCats] = createSignal(CATS.map(() => true))
    const [key, setKey] = createSignal("id"), [dir, setDir] = createSignal(1)
    const [count, setCount] = createSignal(0), [total, setTotal] = createSignal(0)
    const filtered = createMemo(() => { const s = q(), c = cats(); return data.filter((r) => matches(r, s, c)) })
    const view = createMemo(() => filtered().slice().sort(compare(key(), dir())))
    const setSel = (i, on) => {
      const [get, set] = sel[i]
      if (get() === on) return
      set(on)
      setCount((n) => n + (on ? 1 : -1))
      setTotal((t) => t + (on ? data[i].price : -data[i].price))
    }
    step = (a) => batch(() => {
      if (a.t === "q") setQ(a.q)
      else if (a.t === "cat") setCats((c) => { const n = c.slice(); n[a.c] = a.on; return n })
      else if (a.t === "sort") { setKey(a.key); setDir(a.dir) }
      else if (a.t === "sel") setSel(a.i, a.on)
      else if (a.t === "all") for (const r of view()) setSel(r.i, true)
      else for (let i = 0; i < sel.length; i++) setSel(i, false)
    })
    return (
      <div>
        <p class="gsum">{summary(view().length, count(), total())}</p>
        <table class="bt"><tbody>
          <For each={view()}>{(r) => (
            <tr class={sel[r.i][0]() ? SEL : ""}><td class="id">{r.id}</td><td class="nm">{r.name}</td><td class="cat">{CATS[r.cat]}</td><td class="px">{fmtPrice(r.price)}</td><td class="st">{r.stock}</td></tr>
          )}</For>
        </tbody></table>
      </div>
    )
  }, host)
  return { step: (a) => step(a), destroy: dispose }
}

grid.lit:
// Data list, Lit 3: the usual Lit pattern, the state kept in plain variables and a render() of the whole list per
// step through the repeat() directive keyed by id (rows reused and moved by key); the filtered list and the sorted
// view are recomputed only when their inputs change. lit-html walks every visible row's values on each render and
// touches the DOM only where a value changed. Templates in compiled form (../lit-tpl.ts), as the CSP refuses HTML
// strings.
import { render } from "lit/html.js"
import { repeat } from "lit/directives/repeat.js"
import { template, el, attr, child } from "../lit-tpl.ts"
import { CATS, SEL, matches, compare, fmtPrice, summary, type Rec, type Act, type Key } from "./def.ts"
import type { ScenarioApp } from "../core.ts"

export function mount(host: HTMLElement, data: Rec[]): ScenarioApp {
  const row = template(el("tr", { class: attr("class") },
    el("td", { class: "id" }, child()), el("td", { class: "nm" }, child()), el("td", { class: "cat" }, child()),
    el("td", { class: "px" }, child()), el("td", { class: "st" }, child())))
  const page = template(el("div", {}, el("p", { class: "gsum" }, child()), el("table", { class: "bt" }, el("tbody", {}, child()))))
  let q = "", key: Key = "id", dir: 1 | -1 = 1, count = 0, total = 0
  const cats = CATS.map(() => true), sel = new Array<boolean>(data.length).fill(false)
  let filtered: Rec[] = [], view: Rec[] = []
  const refilter = () => { filtered = data.filter((r) => matches(r, q, cats)) }
  const resort = () => { view = filtered.slice().sort(compare(key, dir)) }
  const setSel = (i: number, on: boolean) => {
    if (sel[i] === on) return
    sel[i] = on
    count += on ? 1 : -1
    total += on ? data[i]!.price : -data[i]!.price
  }
  const box = document.createElement("div")
  host.append(box)
  const draw = () => render(page(summary(view.length, count, total),
    repeat(view, (r) => r.id, (r) => row(sel[r.i] ? SEL : "", r.id, r.name, CATS[r.cat], fmtPrice(r.price), r.stock))), box)
  refilter(); resort(); draw()
  return {
    step: (p) => {
      const a = p as Act
      if (a.t === "q" || a.t === "cat") {
        if (a.t === "q") q = a.q
        else cats[a.c] = a.on
        refilter(); resort()
      } else if (a.t === "sort") { key = a.key; dir = a.dir; resort() }
      else if (a.t === "sel") setSel(a.i, a.on)
      else if (a.t === "all") for (const r of view) setSel(r.i, true)
      else for (let i = 0; i < sel.length; i++) setSel(i, false)
      draw()
    },
    destroy: () => { render(null, box); box.remove() },
  }
}

