    el("table", { class: "bt" }, el("tbody", {}, el("template", { "x-for": "r in view()", "x-bind:key": "r.id" },
      el("tr", { "x-bind:class": `sel[r.i] ? '${SEL}' : ''` }, el("td", { class: "id", "x-text": "r.id" }), el("td", { class: "nm", "x-text": "r.name" }),
        el("td", { class: "cat", "x-text": "catName(r.cat)" }), el("td", { class: "px", "x-text": "price(r.price)" }), el("td", { class: "st", "x-text": "r.stock" }))))))
  const s = start<State>(host, root, {
    q: "", cats: CATS.map(() => true), key: "id", dir: 1, sel: data.map(() => false), count: 0, total: 0,
    view(this: State) { const q = this.q, c = this.cats.slice(); return data.filter((r) => matches(r, q, c)).sort(compare(this.key, this.dir)) },
    sum: summary, price: fmtPrice, catName: (c: number) => CATS[c],
  } as State)
  const setSel = (i: number, on: boolean) => {
    if (s.sel[i] === on) return
    s.sel[i] = on; s.count += on ? 1 : -1; s.total += on ? data[i]!.price : -data[i]!.price
  }
  return {
    step: (p) => {
      const a = p as Act
      if (a.t === "q") s.q = a.q
      else if (a.t === "cat") s.cats[a.c] = a.on
      else if (a.t === "sort") { s.key = a.key; s.dir = a.dir }
      else if (a.t === "sel") setSel(a.i, a.on)
      else if (a.t === "all") for (const r of s.view()) setSel(r.i, true)
      else for (let i = 0; i < data.length; i++) setSel(i, false)
    },
    destroy: () => { Alpine.destroyTree(root); root.remove() },
  }
}

grid.angular:
// Data list, Angular: the query, categories and sort are signals; the filtered list and the sorted view are two
// computed(); a @for tracked by record reuses rows. Each record has its own selection signal, so a toggle refreshes
// one row's view and the summary, not the list. Compiled ahead of time with the benchmark app (tools/gen-bench.mjs →
// ../../apps/angular.gen.js).
import { ChangeDetectionStrategy, Component, Input, computed, signal, type WritableSignal } from "@angular/core"
import { mountRoot } from "../angular-host.ts"
import { CATS, SEL, matches, compare, fmtPrice, summary, type Rec, type Act, type Key } from "./def.ts"
import type { ScenarioApp } from "../core.ts"

@Component({
  selector: "bench-grid", changeDetection: ChangeDetectionStrategy.OnPush,
  template: `<div><p class="gsum">{{ sum(view().length, count(), total()) }}</p><table class="bt"><tbody>@for (r of view(); track r.id) {<tr [class]="sel[r.i]!() ? on : ''"><td class="id">{{ r.id }}</td><td class="nm">{{ r.name }}</td><td class="cat">{{ cats[r.cat] }}</td><td class="px">{{ price(r.price) }}</td><td class="st">{{ r.stock }}</td></tr>}</tbody></table></div>`,
})
class Grid {
  @Input({ required: true }) data!: Rec[]
  @Input({ required: true }) sel!: WritableSignal<boolean>[]
  readonly q = signal("")
  readonly catsOn = signal(CATS.map(() => true))
  readonly key = signal<Key>("id")
  readonly dir = signal<1 | -1>(1)
  readonly count = signal(0)
  readonly total = signal(0)
  readonly filtered = computed(() => { const q = this.q(), c = this.catsOn(); return this.data.filter((r) => matches(r, q, c)) })
  readonly view = computed(() => this.filtered().slice().sort(compare(this.key(), this.dir())))
  readonly on = SEL
  readonly cats = CATS
  readonly sum = summary
  readonly price = fmtPrice
}

export async function mount(host: HTMLElement, data: Rec[]): Promise<ScenarioApp> {
  const sel = data.map(() => signal(false))
  const app = await mountRoot(Grid, host, "bench-grid", { data, sel })
  const g = app.instance
  const setSel = (i: number, on: boolean) => {
    if (sel[i]!() === on) return
    sel[i]!.set(on); g.count.update((n) => n + (on ? 1 : -1)); g.total.update((t) => t + (on ? data[i]!.price : -data[i]!.price))
  }
  return {
    step: (p) => app.now(() => {
      const a = p as Act
      if (a.t === "q") g.q.set(a.q)
      else if (a.t === "cat") g.catsOn.update((c) => { const n = c.slice(); n[a.c] = a.on; return n })
      else if (a.t === "sort") { g.key.set(a.key); g.dir.set(a.dir) }
      else if (a.t === "sel") setSel(a.i, a.on)
      else if (a.t === "all") for (const r of g.view()) setSel(r.i, true)
      else for (let i = 0; i < sel.length; i++) setSel(i, false)
    }),
    destroy: app.destroy,
  }
}

hover.vanilla:
// Moving highlight, plain DOM (hand-optimized): the rows are cloned from one prototype and kept in an array; a step
// removes the class from the previously hovered row and adds it to the new one (two class writes).
import { HOVER, type Item } from "./def.ts"
import type { ScenarioApp } from "../core.ts"

export function mount(host: HTMLElement, data: Item[]): ScenarioApp {
  const doc = host.ownerDocument
  const table = doc.createElement("table"), tbody = doc.createElement("tbody")
  table.className = "bt"
  const proto = doc.createElement("tr")
  const id = doc.createElement("td"), lbl = doc.createElement("td")
  id.className = "id"; lbl.className = "lbl"
  id.append(""); lbl.append("")
  proto.append(id, lbl)
  const trs: HTMLTableRowElement[] = []
  for (const it of data) {
    const tr = proto.cloneNode(true) as HTMLTableRowElement
    ;(tr.firstChild!.firstChild as Text).data = String(it.id)
    ;(tr.lastChild!.firstChild as Text).data = it.label
    trs.push(tr); tbody.append(tr)
  }
  table.append(tbody)
  host.append(table)
  let prev: HTMLTableRowElement | null = null
  return {
    step: (p) => {
      const tr = trs[p as number]!
      if (tr === prev) return
      if (prev) prev.className = ""
      tr.className = HOVER
      prev = tr
    },
    destroy: () => table.remove(),
  }
}

hover.march:
// Moving highlight, March: the hovered index is one signal and each row reads it through selector(), so a step
// wakes only the row that loses the highlight and the row that gains it (two class bindings), not 10.000 rows.
import { render, signal, selector } from "march"
import { HOVER, type Item } from "./def.ts"
import type { ScenarioApp } from "../core.ts"

export function mount(host: HTMLElement, data: Item[]): ScenarioApp {
  const hovered = signal(-1)
  const isHovered = selector(() => hovered())
  const dispose = render(() => <table class="bt"><tbody>
    {data.map((it, i) => <tr class={isHovered(i) ? HOVER : ""}><td class="id">{it.id}</td><td class="lbl">{it.label}</td></tr>)}
  </tbody></table>, host)
  return {
    step: (p) => hovered.set(p as number),
    destroy: dispose,
  }
}

hover.react:
// Moving highlight, React 19, with the common recommended pattern: the hovered index is state in the list component
// and each row is a memo component receiving hovered={hovered === i}. A step re-renders the list (10.000 row
// elements created and their props compared) but only the two rows whose boolean changed render again.
// (A useSyncExternalStore selector per row would skip the list render, but memo rows with a boolean prop are what
// React's docs and most code use for selection and hover.) Updates run in flushSync, as a discrete pointer event would.
import { createElement as h, memo, useState } from "react"
import { flushSync } from "react-dom"
import { createRoot } from "react-dom/client"
import { HOVER, type Item } from "./def.ts"
import type { ScenarioApp } from "../core.ts"

const Row = memo(function Row({ it, hovered }: { it: Item; hovered: boolean }) {
  return h("tr", { className: hovered ? HOVER : "" }, h("td", { className: "id" }, it.id), h("td", { className: "lbl" }, it.label))
})
export function mount(host: HTMLElement, data: Item[]): ScenarioApp {
  const api: { set?: (i: number) => void } = {}
  function App() {
    const [hovered, setHovered] = useState(-1)
    api.set = setHovered
    return h("table", { className: "bt" }, h("tbody", null, data.map((it, i) => h(Row, { key: it.id, it, hovered: hovered === i }))))
  }
  const root = createRoot(host)
  flushSync(() => root.render(h(App)))
  return {
    step: (p) => flushSync(() => api.set!(p as number)),
    destroy: () => root.unmount(),
  }
}

hover.preact:
// Moving highlight, Preact 10: the hovered index is state in the list component; rows are class components with
// shouldComponentUpdate on their hovered boolean (the same pattern as memo). A step renders the list (10.000 row
// vnodes compared) and only the two changed rows render again. Preact renders in a microtask, before the paint.
import { h, render, Component } from "preact"
import { HOVER, type Item } from "./def.ts"
import type { ScenarioApp } from "../core.ts"

interface RowProps { it: Item; hovered: boolean }
class RowView extends Component<RowProps> {
  override shouldComponentUpdate(next: RowProps) { return next.hovered !== this.props.hovered || next.it !== this.props.it }
  render({ it, hovered }: RowProps) {
    return h("tr", { class: hovered ? HOVER : "" }, h("td", { class: "id" }, it.id), h("td", { class: "lbl" }, it.label))
  }
}
interface State { hovered: number }
export function mount(host: HTMLElement, data: Item[]): ScenarioApp {
  const api: { app?: Component<object, State> } = {}
  class App extends Component<object, State> {
    constructor(p: object) { super(p); this.state = { hovered: -1 }; api.app = this }
    render(_p: object, { hovered }: State) {
      return h("table", { class: "bt" }, h("tbody", null, data.map((it, i) => h(RowView, { key: it.id, it, hovered: hovered === i }))))
    }
  }
  render(h(App, {}), host)
  return {
    step: (p) => api.app!.setState({ hovered: p as number }),
    destroy: () => render(null, host),
  }
}

hover.vue:
// ── vue.template.html
<table class="bt"><tbody>
  <tr v-for="(it, i) of rows" :key="it.id" v-memo="[i === hovered]" :class="i === hovered ? 'hover' : ''"><td class="id">{{ it.id }}</td><td class="lbl">{{ it.label }}</td></tr>
</tbody></table>

// ── vue.ts
// Moving highlight, Vue 3: the hovered index is a ref; the v-for rows carry v-memo="[i === hovered]", the pattern Vue
// documents for selection in large lists. A step re-runs the list render, but each row whose memo key did not change
// reuses its previous vnode, so only the two changed rows are patched. Template compiled ahead of time
// (vue.template.html → vue.render.gen.js). Vue renders in a microtask, before the paint.
import { createApp, defineComponent, ref, markRaw } from "vue"
import { render } from "./vue.render.gen.js"
import type { Item } from "./def.ts"
import type { ScenarioApp } from "../core.ts"

export function mount(host: HTMLElement, data: Item[]): ScenarioApp {
  const rows = markRaw(data), hovered = ref(-1)
  const App = defineComponent({ setup: () => ({ rows, hovered }), render })
  const app = createApp(App)
  app.mount(host)
  return {
    step: (p) => { hovered.value = p as number },
    destroy: () => app.unmount(),
  }
}

hover.solid:
// Moving highlight, SolidJS: the hovered index is a signal and each row reads it through createSelector, so a step
// wakes only the old and the new row. Compiled with babel-preset-solid (tools/gen-bench.mjs → solid.gen.js).
import { createSignal, createSelector } from "solid-js"
import { render } from "solid-js/web"
import { HOVER } from "./def.ts"

export function mount(host, data) {
  let setHovered
  const dispose = render(() => {
    const [hovered, set] = createSignal(-1)
    setHovered = set
    const isHovered = createSelector(hovered)
    return (
      <table class="bt"><tbody>
        {data.map((it, i) => <tr class={isHovered(i) ? HOVER : ""}><td class="id">{it.id}</td><td class="lbl">{it.label}</td></tr>)}
      </tbody></table>
    )
  }, host)
  return {
    step: (i) => setHovered(i),
    destroy: dispose,
  }
}

hover.lit:
// Moving highlight, Lit 3: the usual Lit pattern, a render() of the whole list with the hovered index; lit-html walks
// every row's three values and touches the DOM only where one changed (the two rows' class). Row template in compiled
// form (../lit-tpl.ts), as the CSP refuses HTML strings.
import { render } from "lit/html.js"
import { template, el, attr, child } from "../lit-tpl.ts"
import { HOVER, type Item } from "./def.ts"
import type { ScenarioApp } from "../core.ts"

export function mount(host: HTMLElement, data: Item[]): ScenarioApp {
  const row = template(el("tr", { class: attr("class") }, el("td", { class: "id" }, child()), el("td", { class: "lbl" }, child())))
  const table = document.createElement("table"), tbody = document.createElement("tbody")
  table.className = "bt"; table.append(tbody); host.append(table)
  const draw = (hovered: number) => render(data.map((it, i) => row(i === hovered ? HOVER : "", it.id, it.label)), tbody)
  draw(-1)
  return {
    step: (p) => draw(p as number),
    destroy: () => { render(null, tbody); table.remove() },
  }
}

hover.inferno:
// Moving highlight, Inferno: the hovered index is app state and each row is a functional component receiving
// hovered={hovered === i}; a step renders the list again (render() is synchronous), and only the two rows whose
// boolean changed render (onComponentShouldUpdate). Compiled with babel-plugin-inferno (tools/gen-bench.mjs →
// inferno.gen.js).
import { render } from "inferno"
import { HOVER } from "./def.ts"

function RowView({ it, hovered }) {
  return <tr className={hovered ? HOVER : ""}><td className="id">{it.id}</td><td className="lbl">{it.label}</td></tr>
}
const changed = (a, b) => a.hovered !== b.hovered || a.it !== b.it

export function mount(host, data) {
  const draw = (h) => render(<table className="bt"><tbody $HasKeyedChildren>{data.map((it, i) => <RowView key={it.id} it={it} hovered={h === i} onComponentShouldUpdate={changed} />)}</tbody></table>, host)
  draw(-1)
  return { step: (i) => draw(i), destroy: () => render(null, host) }
}

hover.ivi:
// Moving highlight, ivi: a keyed List() of row components receiving hovered={hovered === i}; a step updates the list
// and each row skips its update unless its boolean changed, so only two rows are patched (ivi updates synchronously
// in update()). Templates compiled with ivi's template compiler (tools/gen-bench.mjs → ivi.gen.js).
import { createRoot, update, component, List, html } from "ivi"
import { HOVER, type Item } from "./def.ts"
import type { ScenarioApp } from "../core.ts"

interface RowProps { it: Item; hovered: boolean }
const RowView = component<RowProps>(() => ({ it, hovered }) => html`<tr class=${hovered ? HOVER : ""}><td class="id">${it.id}</td><td class="lbl">${it.label}</td></tr>`,
  (a, b) => a.it === b.it && a.hovered === b.hovered)

export function mount(host: HTMLElement, data: Item[]): ScenarioApp {
  const root = createRoot(host)
  const idx = data.map((_, i) => i), key = (i: number) => data[i]!.id
  const draw = (h: number) => update(root, html`<table class="bt"><tbody>${List(idx, key, (i) => RowView({ it: data[i]!, hovered: i === h }))}</tbody></table>`)
  draw(-1)
  return { step: (i) => draw(i as number), destroy: () => update(root, null) }
}

hover.mithril:
// Moving highlight, Mithril: the hovered index is app state; one redraw (m.redraw.sync) per step, and each row
// component skips its diff unless its boolean changed (onbeforeupdate), so only two rows are patched.
import m from "mithril"
import { HOVER, type Item } from "./def.ts"
import type { ScenarioApp } from "../core.ts"

const RowView: m.Component<{ it: Item; hovered: boolean }> = {
  onbeforeupdate: (v, old) => v.attrs.hovered !== old.attrs.hovered || v.attrs.it !== old.attrs.it,
  view: ({ attrs: { it, hovered } }) => m("tr", { class: hovered ? HOVER : "" }, m("td.id", it.id), m("td.lbl", it.label)),
}
export function mount(host: HTMLElement, data: Item[]): ScenarioApp {
  let hovered = -1
  m.mount(host, { view: () => m("table.bt", m("tbody", data.map((it, i) => m(RowView, { key: it.id, it, hovered: i === hovered })))) })
  return { step: (i) => { hovered = i as number; m.redraw.sync() }, destroy: () => m.mount(host, null) }
}

hover.alpine:
// Moving highlight, Alpine.js (CSP build): the hovered index is reactive and each row's class reads it. Alpine has no
// selector primitive, so a step re-runs every row's class binding (10.000 comparisons, in Alpine's microtask before
// the paint) and writes only the two that changed.
import Alpine from "@alpinejs/csp"
import { el, start } from "../../apps/alpine-dom.ts"
import { HOVER, type Item } from "./def.ts"
import type { ScenarioApp } from "../core.ts"

export function mount(host: HTMLElement, data: Item[]): ScenarioApp {
  // <table class="bt"><tbody><template x-for="(it, i) in items" :key="it.id">
  //   <tr :class="hovered === i ? 'hover' : ''"><td class="id" x-text="it.id"></td><td class="lbl" x-text="it.label"></td></tr></template></tbody></table>
  const root = el("table", { class: "bt" }, el("tbody", {}, el("template", { "x-for": "(it, i) in items", "x-bind:key": "it.id" },
