store.vanilla:
// Shared store, plain DOM (hand-optimized): the store is a plain array; the cells are cloned from one prototype and
// their text nodes kept in an array, and a step writes the store and only the changed cells' text.
import { sectionsOf, type StoreData, type Write } from "./def.ts"
import type { ScenarioApp } from "../core.ts"

export function mount(host: HTMLElement, data: StoreData): ScenarioApp {
  const doc = host.ownerDocument
  const cells = data.cells.slice(), texts: Text[] = []
  const grid = doc.createElement("div"), secProto = doc.createElement("div"), proto = doc.createElement("span")
  grid.className = "sg"; secProto.className = "ss"; proto.className = "sc"; proto.append("")
  for (const sec of sectionsOf(cells.length)) {
    const s = secProto.cloneNode(false) as HTMLElement
    for (const i of sec) {
      const c = proto.cloneNode(true) as HTMLElement
      const t = c.firstChild as Text
      t.data = String(cells[i])
      texts.push(t)
      s.append(c)
    }
    grid.append(s)
  }
  host.append(grid)
  return {
    step: (p) => { for (const w of p as Write[]) if (cells[w.i] !== w.v) { cells[w.i] = w.v; texts[w.i]!.data = String(w.v) } },
    destroy: () => grid.remove(),
  }
}

store.march:
// Shared store, March: one store() (src/core/store.ts) holds all the cells; each Cell component reads
// app.cells[i] and so tracks only that path. A step writes the 50 cells inside batch(): only the 50 readers update,
// the sections and the other cells never run again.
import { render, batch, store } from "march"
import { sectionsOf, type StoreData, type Write } from "./def.ts"
import type { ScenarioApp } from "../core.ts"

export function mount(host: HTMLElement, data: StoreData): ScenarioApp {
  const app = store({ cells: data.cells.slice() })
  function Cell(p: { i: number }) {
    return <span class="sc">{app.cells[p.i]}</span>
  }
  function Section(p: { idx: number[] }) {
    return <div class="ss">{p.idx.map((i) => <Cell i={i} />)}</div>
  }
  const dispose = render(() => <div class="sg">{sectionsOf(data.cells.length).map((idx) => <Section idx={idx} />)}</div>, host)
  return {
    step: (p) => batch(() => { for (const w of p as Write[]) app.cells[w.i] = w.v }),
    destroy: dispose,
  }
}

store.react:
// Shared store, React 19, with the pattern React recommends for an external shared store: one store object with a
// subscribe/notify pair, and each memo Cell subscribes with useSyncExternalStore and a per-cell selector
// (() => store.cells[i]). A step writes the 50 cells and notifies once: React runs every subscriber's selector (5.000)
// and re-renders only the cells whose value changed; the sections never render again. Inside flushSync.
import { createElement as h, memo, useSyncExternalStore } from "react"
import { flushSync } from "react-dom"
import { createRoot } from "react-dom/client"
import { sectionsOf, type StoreData, type Write } from "./def.ts"
import type { ScenarioApp } from "../core.ts"

export function mount(host: HTMLElement, data: StoreData): ScenarioApp {
  const listeners = new Set<() => void>()
  const appStore = {
    cells: data.cells.slice(),
    subscribe: (fn: () => void) => { listeners.add(fn); return () => { listeners.delete(fn) } },
    write(ws: Write[]) { for (const w of ws) appStore.cells[w.i] = w.v; for (const fn of listeners) fn() },
  }
  const Cell = memo(function Cell({ i }: { i: number }) {
    const v = useSyncExternalStore(appStore.subscribe, () => appStore.cells[i]!)
    return h("span", { className: "sc" }, v)
  })
  const Section = memo(function Section({ idx }: { idx: number[] }) {
    return h("div", { className: "ss" }, idx.map((i) => h(Cell, { key: i, i })))
  })
  const sections = sectionsOf(data.cells.length)
  const App = () => h("div", { className: "sg" }, sections.map((idx, k) => h(Section, { key: k, idx })))
  const root = createRoot(host)
  flushSync(() => root.render(h(App)))
  return {
    step: (p) => flushSync(() => appStore.write(p as Write[])),
    destroy: () => root.unmount(),
  }
}

store.preact:
// Shared store, Preact 10, the same pattern with hooks: one store object with subscribe/notify; each Cell subscribes
// in useLayoutEffect with a per-cell selector and sets its state only when its value changed (useState skips an equal
// value). A step writes the 50 cells and notifies once: every subscriber's selector runs (5.000), only the changed
// cells re-render; the sections never render again. Preact renders in a microtask, before the paint.
import { h, render, Component } from "preact"
import { useState, useLayoutEffect } from "preact/hooks"
import { sectionsOf, type StoreData, type Write } from "./def.ts"
import type { ScenarioApp } from "../core.ts"

export function mount(host: HTMLElement, data: StoreData): ScenarioApp {
  const listeners = new Set<() => void>()
  const appStore = {
    cells: data.cells.slice(),
    subscribe: (fn: () => void) => { listeners.add(fn); return () => { listeners.delete(fn) } },
    write(ws: Write[]) { for (const w of ws) appStore.cells[w.i] = w.v; for (const fn of listeners) fn() },
  }
  function useCell(i: number): number {
    const [v, set] = useState(() => appStore.cells[i]!)
    useLayoutEffect(() => appStore.subscribe(() => set(appStore.cells[i]!)), [i])
    return v
  }
  const Cell = ({ i }: { i: number }) => h("span", { class: "sc" }, useCell(i))
  class Section extends Component<{ idx: number[] }> {
    override shouldComponentUpdate() { return false }
    render({ idx }: { idx: number[] }) { return h("div", { class: "ss" }, idx.map((i) => h(Cell, { key: i, i }))) }
  }
  render(h("div", { class: "sg" }, sectionsOf(data.cells.length).map((idx, k) => h(Section, { key: k, idx }))), host)
  return {
    step: (p) => appStore.write(p as Write[]),
    destroy: () => render(null, host),
  }
}

store.vue:
// ── vue-cell.template.html
<span class="sc">{{ store.cells[i] }}</span>

// ── vue-section.template.html
<div class="ss"><StoreCell v-for="i of idx" :key="i" :i="i" /></div>

// ── vue.template.html
<div class="sg"><StoreSection v-for="s of sections" :key="s.k" :idx="s.idx" /></div>

// ── vue.ts
// Shared store, Vue 3: one reactive() store holds all the cells; each StoreCell component reads store.cells[i] in its
// template, so it depends on that index only. Sections are components too (templates compiled ahead of time:
// vue.template.html, vue-section.template.html, vue-cell.template.html → *.render.gen.js). A step writes the 50 cells
// and Vue re-renders only those cell components. Vue renders in a microtask, before the paint.
import { createApp, defineComponent, reactive, markRaw } from "vue"
import { render as gridRender } from "./vue.render.gen.js"
import { render as sectionRender } from "./vue-section.render.gen.js"
import { render as cellRender } from "./vue-cell.render.gen.js"
import { sectionsOf, type StoreData, type Write } from "./def.ts"
import type { ScenarioApp } from "../core.ts"

export function mount(host: HTMLElement, data: StoreData): ScenarioApp {
  const appStore = reactive({ cells: data.cells.slice() })
  const sections = markRaw(sectionsOf(data.cells.length).map((idx, k) => markRaw({ k, idx })))
  const StoreCell = defineComponent({ props: { i: { type: Number, required: true } }, setup: () => ({ store: appStore }), render: cellRender })
  const StoreSection = defineComponent({ components: { StoreCell }, props: { idx: { type: Array, required: true } }, render: sectionRender })
  const App = defineComponent({ components: { StoreSection }, setup: () => ({ sections }), render: gridRender })
  const app = createApp(App)
  app.mount(host)
  return {
    step: (p) => { for (const w of p as Write[]) appStore.cells[w.i] = w.v },
    destroy: () => app.unmount(),
  }
}

store.solid:
// Shared store, SolidJS: one createStore (solid-js/store) holds all the cells; each Cell component reads
// store.cells[i], so it depends on that index only. A step writes the 50 cells with setStore inside batch() and Solid
// updates only those texts. Compiled with babel-preset-solid (tools/gen-bench.mjs → solid.gen.js).
import { batch } from "solid-js"
import { createStore } from "solid-js/store"
import { render } from "solid-js/web"
import { sectionsOf } from "./def.ts"

export function mount(host, data) {
