store.lit:
// Shared store, Lit 3: the usual Lit pattern, one plain store object and a render() of the whole page per step;
// lit-html walks every section and every cell's value (5.000) and touches the DOM only where a value changed.
// Templates in compiled form (../lit-tpl.ts), as the CSP refuses HTML strings.
import { render } from "lit/html.js"
import { template, el, child } from "../lit-tpl.ts"
import { sectionsOf, type StoreData, type Write } from "./def.ts"
import type { ScenarioApp } from "../core.ts"

export function mount(host: HTMLElement, data: StoreData): ScenarioApp {
  const cell = template(el("span", { class: "sc" }, child()))
  const section = template(el("div", { class: "ss" }, child()))
  const appStore = { cells: data.cells.slice() }
  const sections = sectionsOf(data.cells.length)
  const grid = document.createElement("div")
  grid.className = "sg"; host.append(grid)
  const draw = () => render(sections.map((idx) => section(idx.map((i) => cell(appStore.cells[i])))), grid)
  draw()
  return {
    step: (p) => { for (const w of p as Write[]) appStore.cells[w.i] = w.v; draw() },
    destroy: () => { render(null, grid); grid.remove() },
  }
}

store.inferno:
// Shared store, Inferno: one small store object holds all the cells, with one listener per cell; each Cell is a class
// component subscribed to its own index. A step writes the 50 cells and notifies only those, whose forceUpdate() is
// synchronous in Inferno; sections and the grid do not render again. Compiled with babel-plugin-inferno
// (tools/gen-bench.mjs → inferno.gen.js).
import { render, Component } from "inferno"
import { sectionsOf } from "./def.ts"

export function mount(host, data) {
  const store = { cells: data.cells.slice(), subs: data.cells.map(() => null) }
  class Cell extends Component {
    componentDidMount() { store.subs[this.props.i] = () => this.forceUpdate() }
    componentWillUnmount() { store.subs[this.props.i] = null }
    render() { return <span className="sc">{store.cells[this.props.i]}</span> }
  }
  const no = () => false
  function Section({ idx }) { return <div className="ss">{idx.map((i) => <Cell i={i} />)}</div> }
  render(<div className="sg">{sectionsOf(data.cells.length).map((idx) => <Section idx={idx} onComponentShouldUpdate={no} />)}</div>, host)
  return {
    step: (writes) => { for (const w of writes) { store.cells[w.i] = w.v; store.subs[w.i]?.() } },
    destroy: () => render(null, host),
  }
}

store.ivi:
// Shared store, ivi: one small store object holds all the cells, with one listener per cell; each cell is a stateful
// component that subscribes to its own index. A step writes the 50 cells and invalidates only those (ivi updates them
// in a microtask, before the paint). Templates compiled with ivi's template compiler (tools/gen-bench.mjs → ivi.gen.js).
import { createRoot, update, component, invalidate, useUnmount, html } from "ivi"
import { sectionsOf, type StoreData, type Write } from "./def.ts"
import type { ScenarioApp } from "../core.ts"

export function mount(host: HTMLElement, data: StoreData): ScenarioApp {
  const store = { cells: data.cells.slice(), subs: data.cells.map((): (() => void) | null => null) }
  const Cell = component<number>((c) => {
    let at = -1
    useUnmount(c, () => { store.subs[at] = null })
    return (i) => { if (at < 0) { at = i; store.subs[i] = () => invalidate(c) } return html`<span class="sc">${store.cells[i]}</span>` }
  }, () => true)
  const root = createRoot(host)
  update(root, html`<div class="sg">${sectionsOf(data.cells.length).map((idx) => html`<div class="ss">${idx.map(Cell)}</div>`)}</div>`)
  return {
    step: (p) => { for (const w of p as Write[]) { store.cells[w.i] = w.v; store.subs[w.i]?.() } },
    destroy: () => update(root, null),
  }
}

store.mithril:
// Shared store, Mithril: one plain store object holds all the cells (Mithril's usual model: state outside the
// components, read in view()); a step writes the 50 cells and redraws once (m.redraw.sync), and each cell component
// skips its diff unless its value changed (onbeforeupdate).
import m from "mithril"
import { sectionsOf, type StoreData, type Write } from "./def.ts"
import type { ScenarioApp } from "../core.ts"

const Cell: m.Component<{ v: number }> = {
  onbeforeupdate: (v, old) => v.attrs.v !== old.attrs.v,
  view: ({ attrs }) => m("span.sc", attrs.v),
}
export function mount(host: HTMLElement, data: StoreData): ScenarioApp {
  const store = { cells: data.cells.slice() }
  const sections = sectionsOf(data.cells.length)
  m.mount(host, { view: () => m("div.sg", sections.map((idx) => m("div.ss", idx.map((i) => m(Cell, { v: store.cells[i]! }))))) })
  return {
    step: (p) => { for (const w of p as Write[]) store.cells[w.i] = w.v; m.redraw.sync() },
    destroy: () => m.mount(host, null),
  }
}

store.alpine:
// Shared store, Alpine.js (CSP build): one Alpine store (Alpine.store, its global state) holds all the cells; each
// cell's x-text reads $store…cells[i], so it depends on that index only, and a step that writes 50 cells re-runs
// just those bindings, in Alpine's microtask (before the paint).
import Alpine from "@alpinejs/csp"
import { el, start } from "../../apps/alpine-dom.ts"
import { sectionsOf, type StoreData, type Write } from "./def.ts"
import type { ScenarioApp } from "../core.ts"

export function mount(host: HTMLElement, data: StoreData): ScenarioApp {
  Alpine.store("benchStore", { cells: data.cells.slice() })
  const store = Alpine.store("benchStore") as { cells: number[] }
  // <div class="sg"><template x-for="idx in sections"><div class="ss">
  //   <template x-for="i in idx" :key="i"><span class="sc" x-text="$store.benchStore.cells[i]"></span></template></div></template></div>
  const root = el("div", { class: "sg" }, el("template", { "x-for": "idx in sections" },
    el("div", { class: "ss" }, el("template", { "x-for": "i in idx", "x-bind:key": "i" }, el("span", { class: "sc", "x-text": "$store.benchStore.cells[i]" })))))
  start(host, root, { sections: sectionsOf(data.cells.length) })
  return {
    step: (p) => { for (const w of p as Write[]) store.cells[w.i] = w.v },
    destroy: () => { Alpine.destroyTree(root); root.remove() },
  }
}

store.angular:
// Shared store, Angular: one injectable store service (Angular's usual app state) holds every cell as a signal; the
// cell bindings read store.cells[i](), so a step that sets 50 signals refreshes only the views that read them.
// Compiled ahead of time with the benchmark app (tools/gen-bench.mjs → ../../apps/angular.gen.js).
import { ChangeDetectionStrategy, Component, Injectable, Input, inject, signal, type WritableSignal } from "@angular/core"
import { mountRoot } from "../angular-host.ts"
import { sectionsOf, type StoreData, type Write } from "./def.ts"
import type { ScenarioApp } from "../core.ts"

@Injectable()
class Store { cells: WritableSignal<number>[] = [] }

@Component({
  selector: "div[stSection]", host: { class: "ss" }, changeDetection: ChangeDetectionStrategy.OnPush,
  template: `@for (i of idx; track i) {<span class="sc">{{ store.cells[i]!() }}</span>}`,
})
class Section { @Input({ required: true }) idx!: number[]; readonly store = inject(Store) }

@Component({
  selector: "bench-store", changeDetection: ChangeDetectionStrategy.OnPush, imports: [Section], providers: [Store],
  template: `<div class="sg">@for (idx of sections; track $index) {<div stSection [idx]="idx"></div>}</div>`,
})
class Grid {
  @Input({ required: true }) sections!: number[][]
  readonly store = inject(Store)
  /** the store's starting state */
  @Input({ required: true }) set cells(v: WritableSignal<number>[]) { this.store.cells = v }
}

export async function mount(host: HTMLElement, data: StoreData): Promise<ScenarioApp> {
  const cells = data.cells.map((v) => signal(v))
  const app = await mountRoot(Grid, host, "bench-store", { sections: sectionsOf(data.cells.length), cells })
  return { step: (p) => app.now(() => { for (const w of p as Write[]) cells[w.i]!.set(w.v) }), destroy: app.destroy }
}

theme.vanilla:
// Theme change, plain DOM (hand-optimized): the cards are cloned from one prototype, the badge elements are kept in an
// array, and a step sets every badge's class. There is no context: the page knows its badges.
import { FIRST, badgeClass, type Card } from "./def.ts"
import type { ScenarioApp } from "../core.ts"

export function mount(host: HTMLElement, data: Card[]): ScenarioApp {
  const doc = host.ownerDocument
  const root = doc.createElement("div"), proto = doc.createElement("div")
  root.className = "cards"; proto.className = "card"
  const h3 = doc.createElement("h3"), p = doc.createElement("p"), badge = doc.createElement("span")
  badge.className = badgeClass(FIRST)
  h3.append(""); p.append(""); badge.append("")
  proto.append(h3, p, badge)
  const badges: HTMLElement[] = []
  for (const c of data) {
    const card = proto.cloneNode(true) as HTMLElement
    ;(card.firstChild!.firstChild as Text).data = c.title
    ;(card.childNodes[1]!.firstChild as Text).data = c.text
    const b = card.lastChild as HTMLElement
    ;(b.firstChild as Text).data = `#${c.id}`
    badges.push(b)
    root.append(card)
  }
  host.append(root)
  return {
    step: (p) => { const cls = badgeClass(p as string); for (const b of badges) b.className = cls },
    destroy: () => root.remove(),
  }
}

theme.march:
// Theme change, March: the theme is provided at the top with context(); its accent is a signal. Each card's
// badge reads it with useContext() and binds it to its class, so a change updates only those 2.000 class bindings:
// the cards themselves and the list never run again.
import { render, signal, context, useContext, type Accessor } from "march"
import { FIRST, badgeClass, type Card } from "./def.ts"
import type { ScenarioApp } from "../core.ts"

interface ThemeValue { accent: Accessor<string> }
const Theme = context<ThemeValue>()

function CardView(props: { c: Card }) {
  const t = useContext(Theme)
  const c = props.c
  return <div class="card"><h3>{c.title}</h3><p>{c.text}</p><span class={badgeClass(t.accent())}>{`#${c.id}`}</span></div>
}

export function mount(host: HTMLElement, data: Card[]): ScenarioApp {
  const accent = signal(FIRST)
  const dispose = render(() => <Theme.Provider value={{ accent }}>
    <div class="cards">{data.map((c) => <CardView c={c} />)}</div>
  </Theme.Provider>, host)
  return { step: (p) => accent.set(p as string), destroy: dispose }
}

theme.react:
// Theme change, React 19, with the pattern React recommends: the theme is a context whose value is memoized; the cards
// and the list are memo components, so a change skips them and React re-renders only the context consumers, the
// 2.000 badge components. Updates run in flushSync.
import { createElement as h, createContext, memo, useContext, useMemo, useState } from "react"
import { flushSync } from "react-dom"
import { createRoot } from "react-dom/client"
import { FIRST, badgeClass, type Card } from "./def.ts"
import type { ScenarioApp } from "../core.ts"

const Theme = createContext({ accent: FIRST })
const Badge = ({ id }: { id: number }) => h("span", { className: badgeClass(useContext(Theme).accent) }, `#${id}`)
const CardView = memo(function CardView({ c }: { c: Card }) {
  return h("div", { className: "card" }, h("h3", null, c.title), h("p", null, c.text), h(Badge, { id: c.id }))
})

export function mount(host: HTMLElement, data: Card[]): ScenarioApp {
  let setAccent: (a: string) => void = () => {}
  const Cards = memo(() => h("div", { className: "cards" }, data.map((c) => h(CardView, { key: c.id, c }))))
  const App = () => {
    const [accent, set] = useState(FIRST)
    setAccent = set
    const value = useMemo(() => ({ accent }), [accent])
    return h(Theme.Provider, { value }, h(Cards))
  }
  const root = createRoot(host)
  flushSync(() => root.render(h(App)))
  return { step: (p) => flushSync(() => setAccent(p as string)), destroy: () => root.unmount() }
}

theme.preact:
// Theme change, Preact 10: the theme is a context provided by the top component; the cards and the list never update
// (shouldComponentUpdate false), and a change re-renders only the context consumers, the 2.000 badge components
// (useContext). Preact renders in a microtask, before the paint.
import { h, render, Component, createContext } from "preact"
import { useContext } from "preact/hooks"
import { FIRST, badgeClass, type Card } from "./def.ts"
import type { ScenarioApp } from "../core.ts"

const Theme = createContext({ accent: FIRST })
const Badge = ({ id }: { id: number }) => h("span", { class: badgeClass(useContext(Theme).accent) }, `#${id}`)
class CardView extends Component<{ c: Card }> {
  override shouldComponentUpdate() { return false }
  render({ c }: { c: Card }) { return h("div", { class: "card" }, h("h3", null, c.title), h("p", null, c.text), h(Badge, { id: c.id })) }
}

export function mount(host: HTMLElement, data: Card[]): ScenarioApp {
  class Cards extends Component {
    override shouldComponentUpdate() { return false }
    render() { return h("div", { class: "cards" }, data.map((c) => h(CardView, { key: c.id, c }))) }
  }
  let app: App | null = null
  class App extends Component<object, { value: { accent: string } }> {
    constructor(p: object) { super(p); this.state = { value: { accent: FIRST } }; app = this }
    render() { return h(Theme.Provider, { value: this.state.value }, h(Cards, null)) }
  }
  render(h(App, null), host)
  return { step: (p) => app!.setState({ value: { accent: p as string } }), destroy: () => render(null, host) }
}

