  <div v-for="c of cards" :key="c.id" class="card"><h3>{{ c.title }}</h3><p>{{ c.text }}</p><ThemeBadge :n="c.id" /></div>
</div>

// ── vue.ts
// Theme change, Vue 3: the top component provide()s a reactive theme object; each card's badge is a small component
// that inject()s it and reads the accent in its template, so a change re-renders only the 2.000 badge components (the
// list does not read the theme and does not render again). Templates compiled ahead of time by Vue's compiler
// (vue.template.html, vue-badge.template.html → *.render.gen.js). Vue renders in a microtask, before the paint.
import { createApp, defineComponent, reactive, markRaw, provide, inject } from "vue"
import { render as listRender } from "./vue.render.gen.js"
import { render as badgeRender } from "./vue-badge.render.gen.js"
import { FIRST, badgeClass, type Card } from "./def.ts"
import type { ScenarioApp } from "../core.ts"

const THEME = Symbol("theme")
export function mount(host: HTMLElement, data: Card[]): ScenarioApp {
  const theme = reactive({ accent: FIRST })
  const cards = markRaw(data)
  const ThemeBadge = defineComponent({ props: { n: { type: Number, required: true } }, setup: () => ({ theme: inject(THEME) as { accent: string }, cls: badgeClass }), render: badgeRender })
  const App = defineComponent({ components: { ThemeBadge }, setup: () => { provide(THEME, theme); return { cards } }, render: listRender })
  const app = createApp(App)
  app.mount(host)
  return { step: (p) => { theme.accent = p as string }, destroy: () => app.unmount() }
}

theme.solid:
// Theme change, SolidJS: the theme is provided at the top with createContext; its accent is a signal. Each card's
// badge reads it with useContext() and binds it to its class, so a change updates only those 2.000 class bindings.
// Compiled with babel-preset-solid (tools/gen-bench.mjs → solid.gen.js).
import { createSignal, createContext, useContext } from "solid-js"
import { render } from "solid-js/web"
import { FIRST, badgeClass } from "./def.ts"

const Theme = createContext()
function CardView(props) {
  const t = useContext(Theme), c = props.c
  return <div class="card"><h3>{c.title}</h3><p>{c.text}</p><span class={badgeClass(t.accent())}>{`#${c.id}`}</span></div>
}

export function mount(host, data) {
  const [accent, setAccent] = createSignal(FIRST)
  const dispose = render(() => (
    <Theme.Provider value={{ accent }}>
      <div class="cards">{data.map((c) => <CardView c={c} />)}</div>
    </Theme.Provider>
  ), host)
  return { step: (a) => setAccent(a), destroy: dispose }
}

theme.lit:
// Theme change, Lit 3: lit-html's core has no context (that is @lit/context, for LitElement components), so the
// accent is passed down in the render: a step renders the whole card list again and lit-html checks every card's
// values, touching the DOM only where one changed (each badge's class). Card template in compiled form
// (../lit-tpl.ts), as the CSP refuses HTML strings.
import { render } from "lit/html.js"
import { template, el, attr, child } from "../lit-tpl.ts"
import { FIRST, badgeClass, type Card } from "./def.ts"
import type { ScenarioApp } from "../core.ts"

export function mount(host: HTMLElement, data: Card[]): ScenarioApp {
  const card = template(el("div", { class: "card" }, el("h3", {}, child()), el("p", {}, child()), el("span", { class: attr("class") }, child())))
  const root = document.createElement("div")
  root.className = "cards"; host.append(root)
  const ids = data.map((c) => `#${c.id}`)
  const draw = (accent: string) => { const cls = badgeClass(accent); render(data.map((c, i) => card(c.title, c.text, cls, ids[i])), root) }
  draw(FIRST)
  return { step: (p) => draw(p as string), destroy: () => { render(null, root); root.remove() } }
}

theme.inferno:
// Theme change, Inferno: Inferno's context does not push changes past components that skip their update, so the
// accent is passed down as a prop and the app renders again (render() is synchronous); each card skips its update
// unless the accent changed, so a change re-renders the 2.000 cards and patches only their badges' class.
// Compiled with babel-plugin-inferno (tools/gen-bench.mjs → inferno.gen.js).
import { render } from "inferno"
import { FIRST, badgeClass } from "./def.ts"

function CardView({ c, accent }) {
  return <div className="card"><h3>{c.title}</h3><p>{c.text}</p><span className={badgeClass(accent)}>{`#${c.id}`}</span></div>
}
const changed = (a, b) => a.accent !== b.accent || a.c !== b.c

export function mount(host, data) {
  const draw = (accent) => render(<div className="cards" $HasKeyedChildren>{data.map((c) => <CardView key={c.id} c={c} accent={accent} onComponentShouldUpdate={changed} />)}</div>, host)
  draw(FIRST)
  return { step: (a) => draw(a), destroy: () => render(null, host) }
}

