  }
}

ticker.solid:
// Live ticker, SolidJS: each quote holds two signals (price and class); a tick sets them inside batch() and Solid
// updates only the bound text and class. Compiled with babel-preset-solid (tools/gen-bench.mjs → solid.gen.js).
import { createSignal, batch } from "solid-js"
import { render } from "solid-js/web"
import { fmtPrice, dir } from "./def.ts"

export function mount(host, data) {
  const rows = data.map((q) => { const [price, setPrice] = createSignal(q.price), [cls, setCls] = createSignal("px"); return { sym: q.sym, price, setPrice, cls, setCls } })
  const dispose = render(() => (
    <table class="bt"><tbody>
      {rows.map((r) => <tr><td class="sym">{r.sym}</td><td class={r.cls()}>{fmtPrice(r.price())}</td></tr>)}
    </tbody></table>
  ), host)
  return {
    step: (ticks) => batch(() => { for (const t of ticks) { const r = rows[t.i]; r.setCls(`px ${dir(t.price, r.price())}`); r.setPrice(t.price) } }),
    destroy: dispose,
  }
}

ticker.lit:
// Live ticker, Lit 3: the usual Lit pattern, a render() of the whole list per tick; lit-html walks every row's values
// and touches the DOM only where a value changed (no virtual DOM, but a value check per row). Row template in compiled
// form (../lit-tpl.ts), as the CSP refuses HTML strings.
import { render } from "lit/html.js"
import { template, el, attr, child } from "../lit-tpl.ts"
import { fmtPrice, dir, type Quote, type Tick } from "./def.ts"
import type { ScenarioApp } from "../core.ts"

export function mount(host: HTMLElement, data: Quote[]): ScenarioApp {
  const row = template(el("tr", {}, el("td", { class: "sym" }, child()), el("td", { class: attr("class") }, child())))
  const rows = data.map((q) => ({ sym: q.sym, price: q.price, cls: "px" }))
  const table = document.createElement("table"), tbody = document.createElement("tbody")
  table.className = "bt"; table.append(tbody); host.append(table)
  const draw = () => render(rows.map((r) => row(r.sym, r.cls, fmtPrice(r.price))), tbody)
  draw()
  return {
    step: (p) => {
      for (const t of p as Tick[]) { const r = rows[t.i]!; r.cls = `px ${dir(t.price, r.price)}`; r.price = t.price }
      draw()
    },
    destroy: () => { render(null, tbody); table.remove() },
  }
}

ticker.inferno:
// Live ticker, Inferno: each row is a class component holding its own quote and registering itself; a tick replaces
// the changed rows' quotes and calls their forceUpdate() (synchronous in Inferno), so only those rows render again.
// Compiled with babel-plugin-inferno (tools/gen-bench.mjs → inferno.gen.js).
import { render, Component } from "inferno"
import { fmtPrice, dir } from "./def.ts"

export function mount(host, data) {
  const rows = []
  class Row extends Component {
    constructor(props) { super(props); this.q = { price: props.q.price, cls: "px" }; rows[props.i] = this }
    set(price) { this.q = { price, cls: `px ${dir(price, this.q.price)}` }; this.forceUpdate() }
    render() { return <tr><td className="sym">{this.props.q.sym}</td><td className={this.q.cls}>{fmtPrice(this.q.price)}</td></tr> }
  }
  render(<table className="bt"><tbody $HasKeyedChildren>{data.map((q, i) => <Row key={q.id} q={q} i={i} />)}</tbody></table>, host)
  return {
    step: (ticks) => { for (const t of ticks) rows[t.i].set(t.price) },
    destroy: () => render(null, host),
  }
}

ticker.ivi:
// Live ticker, ivi: each row is a stateful component that registers a setter; a tick sets the changed rows' quotes
// and invalidates only those components, which ivi updates in a microtask (before the paint). Templates compiled
// with ivi's template compiler (tools/gen-bench.mjs → ivi.gen.js).
import { createRoot, update, component, invalidate, html } from "ivi"
import { fmtPrice, dir, type Quote, type Tick } from "./def.ts"
import type { ScenarioApp } from "../core.ts"

export function mount(host: HTMLElement, data: Quote[]): ScenarioApp {
  const set: ((price: number) => void)[] = []
  const Row = component<{ q: Quote; i: number }>((c) => {
    let price = -1, cls = "px", sym = ""
    return ({ q, i }) => {
      if (price < 0) { price = q.price; sym = q.sym; set[i] = (p) => { cls = `px ${dir(p, price)}`; price = p; invalidate(c) } }
      return html`<tr><td class="sym">${sym}</td><td class=${cls}>${fmtPrice(price)}</td></tr>`
    }
  }, () => true)
  const root = createRoot(host)
  update(root, html`<table class="bt"><tbody>${data.map((q, i) => Row({ q, i }))}</tbody></table>`)
  return {
    step: (p) => { for (const t of p as Tick[]) set[t.i]!(t.price) },
    destroy: () => update(root, null),
  }
}

ticker.mithril:
// Live ticker, Mithril: the usual Mithril pattern, one redraw of the whole view per tick (m.redraw.sync); each row
// component skips its diff unless its quote changed (onbeforeupdate), so Mithril compares 2.000 attrs and patches only
// the changed cells.
import m from "mithril"
import { fmtPrice, dir, type Quote, type Tick } from "./def.ts"
import type { ScenarioApp } from "../core.ts"

interface Cell { sym: string; price: number; cls: string }
const Row: m.Component<{ c: Cell }> = {
  onbeforeupdate: (v, old) => v.attrs.c !== old.attrs.c,
  view: ({ attrs: { c } }) => m("tr", m("td.sym", c.sym), m("td", { class: c.cls }, fmtPrice(c.price))),
}
export function mount(host: HTMLElement, data: Quote[]): ScenarioApp {
  const cells: Cell[] = data.map((q) => ({ sym: q.sym, price: q.price, cls: "px" }))
  m.mount(host, { view: () => m("table.bt", m("tbody", cells.map((c, i) => m(Row, { key: data[i]!.id, c })))) })
  return {
    step: (p) => {
      for (const t of p as Tick[]) { const c = cells[t.i]!; cells[t.i] = { sym: c.sym, price: t.price, cls: `px ${dir(t.price, c.price)}` } }
      m.redraw.sync()
    },
    destroy: () => m.mount(host, null),
  }
}

