tree.vanilla:
// One value deep in a large tree, plain DOM (hand-optimized): the tree is built once, recursively, from two cloned
// prototypes (inner node, leaf); the target leaf's text node is kept, and a step writes only that text.
import type { Tree, TNode } from "./def.ts"
import type { ScenarioApp } from "../core.ts"

export function mount(host: HTMLElement, data: Tree): ScenarioApp {
  const doc = host.ownerDocument
  const box = doc.createElement("div")
  box.className = "tree"
  const inner = doc.createElement("div"), leaf = doc.createElement("div")
  inner.className = "n"; leaf.className = "n leaf"
  const l = doc.createElement("span"), v = doc.createElement("b")
  l.className = "l"; v.className = "v"
  l.append(""); v.append("")
  inner.append(l.cloneNode(true)); leaf.append(l, v)
  let target: Text | null = null
  const build = (parent: HTMLElement, nodes: TNode[]): void => {
    for (const n of nodes) {
      const el = (n.kids ? inner : leaf).cloneNode(true) as HTMLElement
      ;(el.firstChild!.firstChild as Text).data = n.label
      if (n.kids) build(el, n.kids)
      else {
        const t = el.lastChild!.firstChild as Text
        t.data = String(data.values[n.leaf!])
        if (n.leaf === data.target) target = t
      }
      parent.append(el)
    }
  }
  build(box, data.roots)
  host.append(box)
  return {
    step: (p) => { target!.data = String(p as number) },
    destroy: () => box.remove(),
  }
}

tree.march:
// One value deep in a large tree, March: a recursive TreeNode component per node (components run once); each
// leaf's value is a signal, bound to its text node. A step sets the target leaf's signal and only that text updates:
// no component runs again and nothing is compared.
import { render, signal } from "march"
import type { Tree, TNode } from "./def.ts"
import type { ScenarioApp } from "../core.ts"

export function mount(host: HTMLElement, data: Tree): ScenarioApp {
  const cells = data.values.map((v) => signal(v))
  function TreeNode(props: { n: TNode }) {
    const n = props.n
    if (n.kids) return <div class="n"><span class="l">{n.label}</span>{n.kids.map((c) => <TreeNode n={c} />)}</div>
    const cell = cells[n.leaf!]!
    return <div class="n leaf"><span class="l">{n.label}</span><b class="v">{cell()}</b></div>
  }
  const dispose = render(() => <div class="tree">{data.roots.map((c) => <TreeNode n={c} />)}</div>, host)
  return {
    step: (p) => cells[data.target]!.set(p as number),
    destroy: dispose,
  }
}

tree.react:
// One value deep in a large tree, React 19, with the pattern React recommends when one deep value changes often:
// memo components per node, and the leaf values kept outside the tree in a small external store, read with
// useSyncExternalStore by each leaf (one subscription per leaf). A step notifies only the target leaf, so React
// re-renders that one component and reconciles its two elements; its ancestors do not render again. flushSync.
import { createElement as h, memo, useSyncExternalStore } from "react"
import { flushSync } from "react-dom"
import { createRoot } from "react-dom/client"
import type { Tree, TNode } from "./def.ts"
import type { ScenarioApp } from "../core.ts"

export function mount(host: HTMLElement, data: Tree): ScenarioApp {
  const values = data.values.slice()
  const subs: ((() => void) | null)[] = values.map(() => null)
  const Leaf = memo(function Leaf({ n }: { n: TNode }) {
    const i = n.leaf!
    const v = useSyncExternalStore((cb) => { subs[i] = cb; return () => { subs[i] = null } }, () => values[i]!)
    return h("div", { className: "n leaf" }, h("span", { className: "l" }, n.label), h("b", { className: "v" }, v))
  })
  const TreeNode = memo(function TreeNode({ n }: { n: TNode }): ReturnType<typeof h> {
    return h("div", { className: "n" }, h("span", { className: "l" }, n.label), n.kids!.map((c) => h(c.kids ? TreeNode : Leaf, { key: c.id, n: c })))
  })
  const App = () => h("div", { className: "tree" }, data.roots.map((c) => h(TreeNode, { key: c.id, n: c })))
  const root = createRoot(host)
  flushSync(() => root.render(h(App)))
  return {
    step: (p) => flushSync(() => { values[data.target] = p as number; subs[data.target]?.() }),
    destroy: () => root.unmount(),
  }
}

tree.preact:
// One value deep in a large tree, Preact 10: a component per node; the value lives in the leaf itself (a class
// component holding its own state), so a step calls setState on the target leaf only and Preact re-renders and diffs
// that one component; its ancestors do not render again. Preact renders in a microtask, before the paint.
import { h, render, Component, type VNode } from "preact"
import type { Tree, TNode } from "./def.ts"
import type { ScenarioApp } from "../core.ts"

export function mount(host: HTMLElement, data: Tree): ScenarioApp {
  const leaves: (Leaf | null)[] = data.values.map(() => null)
  class Leaf extends Component<{ n: TNode }, { v: number }> {
    constructor(p: { n: TNode }) { super(p); this.state = { v: data.values[p.n.leaf!]! }; leaves[p.n.leaf!] = this }
    override shouldComponentUpdate(_p: unknown, s: { v: number }) { return s.v !== this.state.v }
    render({ n }: { n: TNode }, { v }: { v: number }) { return h("div", { class: "n leaf" }, h("span", { class: "l" }, n.label), h("b", { class: "v" }, v)) }
  }
  class TreeNode extends Component<{ n: TNode }> {
    override shouldComponentUpdate() { return false }
    render({ n }: { n: TNode }): VNode { return h("div", { class: "n" }, h("span", { class: "l" }, n.label), n.kids!.map((c) => (c.kids ? h(TreeNode, { key: c.id, n: c }) : h(Leaf, { key: c.id, n: c })))) }
  }
  render(h("div", { class: "tree" }, data.roots.map((c) => h(TreeNode, { key: c.id, n: c }))), host)
  return {
    step: (p) => leaves[data.target]!.setState({ v: p as number }),
    destroy: () => render(null, host),
  }
}

tree.vue:
// ── vue-node.template.html
<div v-if="n.kids" class="n"><span class="l">{{ n.label }}</span><TreeNode v-for="c of n.kids" :key="c.id" :n="c" /></div>
<div v-else class="n leaf"><span class="l">{{ n.label }}</span><b class="v">{{ cells[n.leaf].v }}</b></div>

// ── vue.template.html
<div class="tree"><TreeNode v-for="c of roots" :key="c.id" :n="c" /></div>

// ── vue.ts
// One value deep in a large tree, Vue 3: a recursive TreeNode component per node (templates compiled ahead of time by
// Vue's compiler: vue.template.html, vue-node.template.html → *.render.gen.js). The tree itself is plain (markRaw);
// each leaf value is a reactive object read only in that leaf's render, so a step re-renders and patches only the
// target leaf component. Vue renders in a microtask, before the paint.
import { createApp, defineComponent, reactive, markRaw } from "vue"
import { render as treeRender } from "./vue.render.gen.js"
import { render as nodeRender } from "./vue-node.render.gen.js"
import type { Tree } from "./def.ts"
import type { ScenarioApp } from "../core.ts"

export function mount(host: HTMLElement, data: Tree): ScenarioApp {
  const cells = markRaw(data.values.map((v) => reactive({ v })))
  const roots = markRaw(data.roots)
  const TreeNode = defineComponent({ name: "TreeNode", props: { n: { type: Object, required: true } }, setup: () => ({ cells }), render: nodeRender })
  TreeNode.components = { TreeNode }
  const App = defineComponent({ components: { TreeNode }, setup: () => ({ roots }), render: treeRender })
  const app = createApp(App)
  app.mount(host)
  return {
    step: (p) => { cells[data.target]!.v = p as number },
    destroy: () => app.unmount(),
  }
}

tree.solid:
// One value deep in a large tree, SolidJS: a recursive TreeNode component per node (components run once); each leaf
// value is a signal bound to its text node, so a step sets one signal and Solid updates only that text.
// Compiled with babel-preset-solid (tools/gen-bench.mjs → solid.gen.js).
import { createSignal } from "solid-js"
import { render } from "solid-js/web"

export function mount(host, data) {
  const cells = data.values.map((v) => createSignal(v))
  function TreeNode(props) {
    const n = props.n
    if (n.kids) return <div class="n"><span class="l">{n.label}</span>{n.kids.map((c) => <TreeNode n={c} />)}</div>
    const [v] = cells[n.leaf]
    return <div class="n leaf"><span class="l">{n.label}</span><b class="v">{v()}</b></div>
  }
  const dispose = render(() => <div class="tree">{data.roots.map((c) => <TreeNode n={c} />)}</div>, host)
  return {
    step: (v) => cells[data.target][1](v),
    destroy: dispose,
  }
}

tree.lit:
// One value deep in a large tree, Lit 3: the usual Lit pattern, a render() of the whole tree per step from its data
// (one template per node, recursively); lit-html walks every node's values and touches the DOM only where a value
// changed (no virtual DOM, but a value check per node). Templates in compiled form (../lit-tpl.ts), as the CSP
// refuses HTML strings.
import { render, type TemplateResult } from "lit/html.js"
import { template, el, child } from "../lit-tpl.ts"
import type { Tree, TNode } from "./def.ts"
import type { ScenarioApp } from "../core.ts"

export function mount(host: HTMLElement, data: Tree): ScenarioApp {
  const inner = template(el("div", { class: "n" }, el("span", { class: "l" }, child()), child()))
  const leaf = template(el("div", { class: "n leaf" }, el("span", { class: "l" }, child()), el("b", { class: "v" }, child())))
  const values = data.values.slice()
  const box = document.createElement("div")
  box.className = "tree"; host.append(box)
  const node = (n: TNode): TemplateResult => (n.kids ? inner(n.label, n.kids.map(node)) : leaf(n.label, values[n.leaf!]))
  const draw = () => render(data.roots.map(node), box)
  draw()
  return {
    step: (p) => { values[data.target] = p as number; draw() },
    destroy: () => { render(null, box); box.remove() },
  }
}

tree.inferno:
// One value deep in a large tree, Inferno: functional components per node (rendered once, then skipped: their node
// never changes), and each leaf a class component holding its value; the target leaf registers itself and a step
// calls its forceUpdate() (synchronous in Inferno), so only that leaf renders again.
// Compiled with babel-plugin-inferno (tools/gen-bench.mjs → inferno.gen.js).
import { render, Component } from "inferno"

export function mount(host, data) {
  let target = null
  class Leaf extends Component {
    constructor(props) { super(props); this.v = data.values[props.n.leaf]; if (props.n.leaf === data.target) target = this }
    set(v) { this.v = v; this.forceUpdate() }
    render() { const n = this.props.n; return <div className="n leaf"><span className="l">{n.label}</span><b className="v">{this.v}</b></div> }
  }
  function TreeNode({ n }) {
    return <div className="n"><span className="l">{n.label}</span>{n.kids.map((c) => (c.kids ? <TreeNode key={c.id} n={c} onComponentShouldUpdate={no} /> : <Leaf key={c.id} n={c} />))}</div>
  }
  const no = () => false
  render(<div className="tree">{data.roots.map((c) => <TreeNode key={c.id} n={c} onComponentShouldUpdate={no} />)}</div>, host)
  return {
    step: (v) => target.set(v),
    destroy: () => render(null, host),
  }
}

tree.ivi:
// One value deep in a large tree, ivi: inner nodes are plain template functions (drawn once), each leaf a stateful
// component holding its value; the target leaf registers a setter, and a step sets it and invalidates that one
// component, which ivi updates in a microtask (before the paint). Templates compiled with ivi's template compiler
// (tools/gen-bench.mjs → ivi.gen.js).
import { createRoot, update, component, invalidate, html, type VAny } from "ivi"
import type { Tree, TNode } from "./def.ts"
import type { ScenarioApp } from "../core.ts"

export function mount(host: HTMLElement, data: Tree): ScenarioApp {
  let set: (v: number) => void = () => {}
  const Leaf = component<TNode>((c) => {
    let v = -1
    return (n) => {
      if (v < 0) { v = data.values[n.leaf!]!; if (n.leaf === data.target) set = (x) => { v = x; invalidate(c) } }
      return html`<div class="n leaf"><span class="l">${n.label}</span><b class="v">${v}</b></div>`
    }
  }, () => true)
  const node = (n: TNode): VAny => (n.kids ? html`<div class="n"><span class="l">${n.label}</span>${n.kids.map(node)}</div>` : Leaf(n))
  const root = createRoot(host)
  update(root, html`<div class="tree">${data.roots.map(node)}</div>`)
  return {
    step: (v) => set(v as number),
    destroy: () => update(root, null),
  }
}

tree.mithril:
// One value deep in a large tree, Mithril: one redraw per step (m.redraw.sync), with Mithril's own way to keep it
// small: a node component skips its subtree (onbeforeupdate) unless the changed leaf is under it, so the redraw
// walks only the four nodes on the path and the leaf.
import m from "mithril"
import type { Tree, TNode } from "./def.ts"
import type { ScenarioApp } from "../core.ts"

export function mount(host: HTMLElement, data: Tree): ScenarioApp {
  const values = data.values.slice()
  // the nodes on the path to the target leaf: their subtrees are the only ones that can change
  const path = new Set<number>()
  const find = (ns: TNode[]): boolean => ns.some((n) => (n.leaf === data.target || (!!n.kids && find(n.kids))) && (path.add(n.id), true))
  find(data.roots)
  const Node: m.Component<{ n: TNode }> = {
    onbeforeupdate: (v) => path.has(v.attrs.n.id),
    view: ({ attrs: { n } }) => (n.kids
      ? m("div.n", m("span.l", n.label), n.kids.map((c) => m(Node, { key: c.id, n: c })))
      : m("div.n.leaf", m("span.l", n.label), m("b.v", values[n.leaf!]))),
  }
  m.mount(host, { view: () => m("div.tree", data.roots.map((c) => m(Node, { key: c.id, n: c }))) })
  return {
    step: (v) => { values[data.target] = v as number; m.redraw.sync() },
    destroy: () => m.mount(host, null),
  }
}

tree.alpine:
// One value deep in a large tree, Alpine.js (CSP build): Alpine has no recursive templates, so the four levels are
// four nested x-for templates; the leaf values are a reactive array and each leaf's x-text reads only its own entry,
// so a step that sets one entry re-runs one binding (in Alpine's microtask, before the paint).
import Alpine from "@alpinejs/csp"
import { el, start } from "../../apps/alpine-dom.ts"
import type { Tree } from "./def.ts"
import type { ScenarioApp } from "../core.ts"

export function mount(host: HTMLElement, data: Tree): ScenarioApp {
  // <div class="tree"><template x-for="a in roots" :key="a.id"><div class="n"><span class="l" x-text="a.label"></span>
  //   <template x-for="b in a.kids" …> … <template x-for="d in c.kids" :key="d.id">
  //     <div class="n leaf"><span class="l" x-text="d.label"></span><b class="v" x-text="values[d.leaf]"></b></div>
  const level = (v: string, of: string, inner: HTMLElement): HTMLElement => el("template", { "x-for": `${v} in ${of}`, "x-bind:key": `${v}.id` }, inner)
  const inner = (v: string, kids: HTMLElement): HTMLElement => el("div", { class: "n" }, el("span", { class: "l", "x-text": `${v}.label` }), kids)
  const leaf = el("div", { class: "n leaf" }, el("span", { class: "l", "x-text": "d.label" }), el("b", { class: "v", "x-text": "values[d.leaf]" }))
  const root = el("div", { class: "tree" }, level("a", "roots", inner("a", level("b", "a.kids", inner("b", level("c", "b.kids", inner("c", level("d", "c.kids", leaf))))))))
  const s = start(host, root, { roots: Alpine.raw(data.roots), values: data.values.slice() })
  return {
    step: (v) => { s.values[data.target] = v as number },
    destroy: () => { Alpine.destroyTree(root); root.remove() },
  }
}

tree.angular:
// One value deep in a large tree, Angular: a recursive OnPush component per inner node and a leaf component reading
// its own value signal, so a step that sets one signal refreshes only that leaf's view.
// Compiled ahead of time with the benchmark app (tools/gen-bench.mjs → ../../apps/angular.gen.js).
import { ChangeDetectionStrategy, Component, Input, signal, type WritableSignal } from "@angular/core"
import { mountRoot } from "../angular-host.ts"
import type { Tree, TNode } from "./def.ts"
import type { ScenarioApp } from "../core.ts"

@Component({
  selector: "div[tLeaf]", host: { class: "n leaf" }, changeDetection: ChangeDetectionStrategy.OnPush,
  template: `<span class="l">{{ n.label }}</span><b class="v">{{ v() }}</b>`,
})
class LeafView { @Input({ required: true }) n!: TNode; @Input({ required: true }) v!: WritableSignal<number> }

@Component({
  selector: "div[tNode]", host: { class: "n" }, changeDetection: ChangeDetectionStrategy.OnPush, imports: [LeafView],
  template: `<span class="l">{{ n.label }}</span>@for (c of n.kids; track c.id) {@if (c.kids) {<div tNode [n]="c" [vs]="vs"></div>} @else {<div tLeaf [n]="c" [v]="vs[c.leaf!]"></div>}}`,
})
class NodeView { @Input({ required: true }) n!: TNode; @Input({ required: true }) vs!: WritableSignal<number>[] }

@Component({
  selector: "bench-tree", changeDetection: ChangeDetectionStrategy.OnPush, imports: [NodeView],
  template: `<div class="tree">@for (c of roots; track c.id) {<div tNode [n]="c" [vs]="vs"></div>}</div>`,
})
class TreeView { @Input({ required: true }) roots!: TNode[]; @Input({ required: true }) vs!: WritableSignal<number>[] }

export async function mount(host: HTMLElement, data: Tree): Promise<ScenarioApp> {
  const vs = data.values.map((v) => signal(v))
  const app = await mountRoot(TreeView, host, "bench-tree", { roots: data.roots, vs })
  return {
    step: (v) => app.now(() => vs[data.target]!.set(v as number)),
    destroy: app.destroy,
  }
}
